export const AMC10_FLASHCARDS: AMC10Flashcard[] = [
  { id: "amc10-0001", level: "core", deck: "arithmetic", category: "算术", front: "运算顺序是什么？", back: "括号→指数/根式→乘除→加减；同级从左到右。", source: "amc10-concept", verified: true },
  { id: "amc10-0002", level: "core", deck: "arithmetic", category: "算术", front: "分配律是什么？", back: "a(b+c)=ab+ac；反向使用可提取公因式。", source: "amc10-concept", verified: true },
  { id: "amc10-0003", level: "core", deck: "arithmetic", category: "算术", front: "平方差公式是什么？", back: "a²-b²=(a-b)(a+b)。", source: "amc10-concept", verified: true },
  { id: "amc10-0004", level: "core", deck: "arithmetic", category: "算术", front: "完全平方公式是什么？", back: "(a±b)²=a²±2ab+b²。", source: "amc10-concept", verified: true },
  { id: "amc10-0005", level: "core", deck: "arithmetic", category: "算术", front: "绝对值|x|表示什么？", back: "x到0的距离；永远非负。", source: "amc10-concept", verified: true },
  { id: "amc10-0006", level: "core", deck: "arithmetic", category: "算术", front: "科学记数法的标准形式是什么？", back: "a×10^n，其中1≤|a|<10且n为整数。", source: "amc10-concept", verified: true },
  { id: "amc10-0007", level: "core", deck: "arithmetic", category: "算术", front: "比例a/b=c/d如何交叉相乘？", back: "在分母非零时得到ad=bc。", source: "amc10-concept", verified: true },
  { id: "amc10-0008", level: "core", deck: "arithmetic", category: "算术", front: "正比例和反比例的模型分别是什么？", back: "正比例y=kx；反比例y=k/x或xy=k（都要求k≠0，反比例还需x≠0）。", source: "amc10-concept", verified: true },
  { id: "amc10-0009", level: "core", deck: "arithmetic", category: "算术", front: "连续两次百分比变化能直接相加吗？", back: "通常不能；总倍率为各次倍率的乘积。", source: "amc10-concept", verified: true },
  { id: "amc10-0010", level: "core", deck: "arithmetic", category: "算术", front: "增长r%和减少r%的倍率是什么？", back: "分别为1+r/100和1-r/100。", source: "amc10-concept", verified: true },
  { id: "amc10-0011", level: "core", deck: "arithmetic", category: "算术", front: "先涨r%再跌r%会回到原值吗？", back: "不会；倍率是1-(r/100)²。", source: "amc10-concept", verified: true },
  { id: "amc10-0012", level: "core", deck: "arithmetic", category: "算术", front: "加权平均公式是什么？", back: "加权和/权重总和。", source: "amc10-concept", verified: true },
  { id: "amc10-0013", level: "core", deck: "arithmetic", category: "算术", front: "平均数反推总和的方法是什么？", back: "总和=平均数×数据个数。", source: "amc10-concept", verified: true },
  { id: "amc10-0014", level: "core", deck: "arithmetic", category: "算术", front: "两组数据合并平均数如何求？", back: "(n₁a₁+n₂a₂)/(n₁+n₂)。", source: "amc10-concept", verified: true },
  { id: "amc10-0015", level: "core", deck: "arithmetic", category: "算术", front: "等路程往返、速度为u,v时平均速度是多少？", back: "2uv/(u+v)，不是算术平均。", source: "amc10-concept", verified: true },
  { id: "amc10-0016", level: "core", deck: "arithmetic", category: "算术", front: "路程、速度、时间关系是什么？", back: "d=rt；统一单位后再列式。", source: "amc10-concept", verified: true },
  { id: "amc10-0017", level: "core", deck: "arithmetic", category: "算术", front: "相向运动的相对速度是什么？", back: "两速度之和。", source: "amc10-concept", verified: true },
  { id: "amc10-0018", level: "core", deck: "arithmetic", category: "算术", front: "同向追及的相对速度是什么？", back: "较快速度减较慢速度。", source: "amc10-concept", verified: true },
  { id: "amc10-0019", level: "core", deck: "arithmetic", category: "算术", front: "工作率模型是什么？", back: "工作量=工作率×时间；共同工作时工作率相加。", source: "amc10-concept", verified: true },
  { id: "amc10-0020", level: "core", deck: "arithmetic", category: "算术", front: "浓度模型的守恒量是什么？", back: "溶质质量；浓度=溶质/混合物总量。", source: "amc10-concept", verified: true },
  { id: "amc10-0021", level: "core", deck: "arithmetic", category: "算术", front: "比例尺放大k倍时长度、面积、体积如何变化？", back: "分别乘k,k²,k³。", source: "amc10-concept", verified: true },
  { id: "amc10-0022", level: "core", deck: "arithmetic", category: "算术", front: "量纲检查有什么用？", back: "检查相加量是否同单位、答案单位是否合理。", source: "amc10-concept", verified: true },
  { id: "amc10-0023", level: "core", deck: "arithmetic", category: "算术", front: "上下界估算的基本原则是什么？", back: "对正量按运算方向选择上下界，并在最后检查误差方向。", source: "amc10-concept", verified: true },
  { id: "amc10-0024", level: "advance", deck: "arithmetic", category: "算术", front: "调和平均公式是什么？", back: "正数x₁,...,x_n的调和平均为n/(Σ1/x_i)。", source: "amc10-concept", verified: true },
  { id: "amc10-0025", level: "core", deck: "arithmetic", category: "数论", front: "a|b是什么意思？", back: "存在整数k使b=ak。", source: "amc10-concept", verified: true },
  { id: "amc10-0026", level: "core", deck: "arithmetic", category: "数论", front: "质数的定义是什么？", back: "大于1且正因数只有1和自身的整数；1不是质数。", source: "amc10-concept", verified: true },
  { id: "amc10-0027", level: "core", deck: "arithmetic", category: "数论", front: "唯一质因数分解定理说什么？", back: "每个大于1的整数都能唯一写成质数幂的乘积，忽略排列顺序。", source: "amc10-concept", verified: true },
  { id: "amc10-0028", level: "core", deck: "arithmetic", category: "数论", front: "gcd(a,b)是什么？", back: "同时整除a,b的最大正整数。", source: "amc10-concept", verified: true },
  { id: "amc10-0029", level: "core", deck: "arithmetic", category: "数论", front: "lcm(a,b)是什么？", back: "同时被a,b整除的最小正整数。", source: "amc10-concept", verified: true },
  { id: "amc10-0030", level: "core", deck: "arithmetic", category: "数论", front: "gcd与lcm的乘积关系是什么？", back: "对正整数，gcd(a,b)·lcm(a,b)=ab。", source: "amc10-concept", verified: true },
  { id: "amc10-0031", level: "core", deck: "arithmetic", category: "数论", front: "欧几里得算法是什么？", back: "gcd(a,b)=gcd(b,a mod b)，重复至余数为0。", source: "amc10-concept", verified: true },
  { id: "amc10-0032", level: "core", deck: "arithmetic", category: "数论", front: "若n=p₁^a₁...p_k^a_k，正约数个数是多少？", back: "(a₁+1)...(a_k+1)。", source: "amc10-concept", verified: true },
  { id: "amc10-0033", level: "advance", deck: "arithmetic", category: "数论", front: "若n=p₁^a₁...p_k^a_k，正约数和是多少？", back: "∏(1+p_i+...+p_i^{a_i})。", source: "amc10-concept", verified: true },
  { id: "amc10-0034", level: "advance", deck: "arithmetic", category: "数论", front: "正约数乘积是多少？", back: "n^{d(n)/2}；完全平方时中间的√n单独配对也仍成立。", source: "amc10-concept", verified: true },
  { id: "amc10-0035", level: "core", deck: "arithmetic", category: "数论", front: "一个整数是完全平方的质因数条件是什么？", back: "每个质因数指数均为偶数。", source: "amc10-concept", verified: true },
  { id: "amc10-0036", level: "core", deck: "arithmetic", category: "数论", front: "一个整数是完全立方的质因数条件是什么？", back: "每个质因数指数均为3的倍数。", source: "amc10-concept", verified: true },
  { id: "amc10-0037", level: "core", deck: "arithmetic", category: "数论", front: "如何求使n乘上最小正整数后成为平方？", back: "把质因数分解中所有奇指数各补1。", source: "amc10-concept", verified: true },
  { id: "amc10-0038", level: "core", deck: "arithmetic", category: "数论", front: "被2整除的判定是什么？", back: "个位数字为偶数。", source: "amc10-concept", verified: true },
  { id: "amc10-0039", level: "core", deck: "arithmetic", category: "数论", front: "被3整除的判定是什么？", back: "各位数字和被3整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0040", level: "core", deck: "arithmetic", category: "数论", front: "被4整除的判定是什么？", back: "末两位组成的数被4整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0041", level: "core", deck: "arithmetic", category: "数论", front: "被5整除的判定是什么？", back: "个位为0或5。", source: "amc10-concept", verified: true },
  { id: "amc10-0042", level: "core", deck: "arithmetic", category: "数论", front: "被8整除的判定是什么？", back: "末三位组成的数被8整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0043", level: "core", deck: "arithmetic", category: "数论", front: "被9整除的判定是什么？", back: "各位数字和被9整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0044", level: "core", deck: "arithmetic", category: "数论", front: "被10整除的判定是什么？", back: "个位为0。", source: "amc10-concept", verified: true },
  { id: "amc10-0045", level: "core", deck: "arithmetic", category: "数论", front: "被11整除的判定是什么？", back: "奇数位数字和与偶数位数字和之差被11整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0046", level: "core", deck: "arithmetic", category: "数论", front: "若质数p|ab，能推出什么？", back: "p|a或p|b；这不能直接推广到合数。", source: "amc10-concept", verified: true },
  { id: "amc10-0047", level: "core", deck: "arithmetic", category: "数论", front: "两个整数互质是什么意思？", back: "gcd为1；不要求两者都是质数。", source: "amc10-concept", verified: true },
  { id: "amc10-0048", level: "core", deck: "arithmetic", category: "数论", front: "连续整数的gcd有什么性质？", back: "相邻两个整数互质。", source: "amc10-concept", verified: true },
  { id: "amc10-0049", level: "advance", deck: "arithmetic", category: "数论", front: "n!中质数p的指数如何求？", back: "⌊n/p⌋+⌊n/p²⌋+...。", source: "amc10-concept", verified: true },
  { id: "amc10-0050", level: "core", deck: "arithmetic", category: "数论", front: "n!末尾0的个数如何求？", back: "求因子5的指数，因为因子2更多。", source: "amc10-concept", verified: true },
  { id: "amc10-0051", level: "core", deck: "arithmetic", category: "数论", front: "因数对最接近何处时和最小？", back: "√n附近；整数题要实际检查相邻因数对。", source: "amc10-concept", verified: true },
  { id: "amc10-0052", level: "advance", deck: "arithmetic", category: "数论", front: "平方差a²-b²可写成什么因数结构？", back: "(a-b)(a+b)，两因数同奇偶。", source: "amc10-concept", verified: true },
  { id: "amc10-0053", level: "core", deck: "arithmetic", category: "数论", front: "a≡b (mod m)是什么意思？", back: "m|(a-b)，即两数除以m余数相同。", source: "amc10-concept", verified: true },
  { id: "amc10-0054", level: "core", deck: "arithmetic", category: "数论", front: "同余可以进行哪些基本运算？", back: "可同模相加、相减、相乘；幂只对非负整数次幂无条件成立，用负指数前必须先确认gcd(a,m)=1。", source: "amc10-concept", verified: true },
  { id: "amc10-0055", level: "core", deck: "arithmetic", category: "数论", front: "同余式能随意约分吗？", back: "不能；只有约去的数与模互质，或同时正确缩小模数时才安全。", source: "amc10-concept", verified: true },
  { id: "amc10-0056", level: "core", deck: "arithmetic", category: "数论", front: "求大幂末位的常用方法是什么？", back: "对模10观察幂的周期。", source: "amc10-concept", verified: true },
  { id: "amc10-0057", level: "core", deck: "arithmetic", category: "数论", front: "求末两位应使用什么模？", back: "模100。", source: "amc10-concept", verified: true },
  { id: "amc10-0058", level: "core", deck: "arithmetic", category: "数论", front: "为什么先缩小底数再乘方？", back: "若a≡r (mod m)，则a^n≡r^n (mod m)，计算更小。", source: "amc10-concept", verified: true },
  { id: "amc10-0059", level: "core", deck: "arithmetic", category: "数论", front: "奇偶性对应什么模？", back: "模2。", source: "amc10-concept", verified: true },
  { id: "amc10-0060", level: "core", deck: "arithmetic", category: "数论", front: "平方数模4可能是什么？", back: "0或1。", source: "amc10-concept", verified: true },
  { id: "amc10-0061", level: "core", deck: "arithmetic", category: "数论", front: "平方数模8可能是什么？", back: "0、1或4；奇数平方模8为1。", source: "amc10-concept", verified: true },
  { id: "amc10-0062", level: "core", deck: "arithmetic", category: "数论", front: "平方数模3可能是什么？", back: "0或1。", source: "amc10-concept", verified: true },
  { id: "amc10-0063", level: "core", deck: "arithmetic", category: "数论", front: "数字和为什么能判断模9？", back: "10≡1 (mod 9)，所以原数与数字和同余。", source: "amc10-concept", verified: true },
  { id: "amc10-0064", level: "advance", deck: "arithmetic", category: "数论", front: "交错数字和为什么能判断模11？", back: "10≡-1 (mod 11)。", source: "amc10-concept", verified: true },
  { id: "amc10-0065", level: "core", deck: "arithmetic", category: "数论", front: "线性同余ax≡b (mod m)何时有解？", back: "当且仅当gcd(a,m)|b。", source: "amc10-concept", verified: true },
  { id: "amc10-0066", level: "advance", deck: "arithmetic", category: "数论", front: "当gcd(a,m)=1时如何解ax≡b？", back: "求a的模逆元，再两边乘逆元。", source: "amc10-concept", verified: true },
  { id: "amc10-0067", level: "advance", deck: "arithmetic", category: "数论", front: "多个互质模条件如何处理？", back: "可逐步列候选或使用中国剩余思想合并周期；AMC 10通常不需背一般公式。", source: "amc10-concept", verified: true },
  { id: "amc10-0068", level: "core", deck: "arithmetic", category: "数论", front: "周期题第一步是什么？", back: "写出足够多项，确认起点、周期长度和索引偏移。", source: "amc10-concept", verified: true },
  { id: "amc10-0069", level: "core", deck: "arithmetic", category: "数论", front: "b进制数(a_na_{n-1}...a_0)_b的值是什么？", back: "Σa_i b^i，且每位满足0≤a_i<b。", source: "amc10-concept", verified: true },
  { id: "amc10-0070", level: "core", deck: "arithmetic", category: "数论", front: "如何把十进制整数转成b进制？", back: "反复除以b并倒序读取余数。", source: "amc10-concept", verified: true },
  { id: "amc10-0071", level: "core", deck: "arithmetic", category: "数论", front: "一个n位b进制正整数的范围是什么？", back: "b^{n-1}到b^n-1。", source: "amc10-concept", verified: true },
  { id: "amc10-0072", level: "core", deck: "arithmetic", category: "数论", front: "两位数10a+b倒序后是什么？", back: "10b+a；两者差为9(a-b)。", source: "amc10-concept", verified: true },
  { id: "amc10-0073", level: "core", deck: "arithmetic", category: "数论", front: "三位数100a+10b+c如何翻译？", back: "按位值直接写，首位a≠0。", source: "amc10-concept", verified: true },
  { id: "amc10-0074", level: "core", deck: "arithmetic", category: "数论", front: "数字构造题最常漏掉什么？", back: "首位不能为0、数字是否可重复、位数和进制范围。", source: "amc10-concept", verified: true },
  { id: "amc10-0075", level: "core", deck: "arithmetic", category: "数论", front: "线性不定方程ax+by=c何时有整数解？", back: "当且仅当gcd(a,b)|c。", source: "amc10-concept", verified: true },
  { id: "amc10-0076", level: "core", deck: "arithmetic", category: "数论", front: "如何参数化线性不定方程的全部整数解？", back: "从一个特解出发，x=x₀+(b/g)t,y=y₀-(a/g)t，其中g=gcd(a,b)。", source: "amc10-concept", verified: true },
  { id: "amc10-0077", level: "core", deck: "arithmetic", category: "数论", front: "正整数解与非负整数解的区别是什么？", back: "正整数至少为1；非负整数允许0，参数范围不同。", source: "amc10-concept", verified: true },
  { id: "amc10-0078", level: "advance", deck: "arithmetic", category: "数论", front: "Frobenius两数结论是什么？", back: "互质正整数a,b不能表示为ax+by的最大非负目标数是ab-a-b；只在条件吻合时用。", source: "amc10-concept", verified: true },
  { id: "amc10-0079", level: "core", deck: "arithmetic", category: "数论", front: "有理根定理的基础版本是什么？", back: "整系数首一多项式的整数根必须整除常数项。", source: "amc10-concept", verified: true },
  { id: "amc10-0080", level: "advance", deck: "arithmetic", category: "数论", front: "整值条件常如何转化？", back: "用带余除法、因式分解或同余把分母整除分子写出来。", source: "amc10-concept", verified: true },
  { id: "amc10-0081", level: "core", deck: "arithmetic", category: "数论", front: "证明不存在整数解的常用工具是什么？", back: "奇偶、模3/4/8/9、平方余数或因数奇偶性。", source: "amc10-concept", verified: true },
  { id: "amc10-0082", level: "advance", deck: "arithmetic", category: "数论", front: "xy为完全平方能否推出x,y都是平方？", back: "不能；只能说明两者各质因数指数奇偶性相同部分可配对。", source: "amc10-concept", verified: true },
  { id: "amc10-0083", level: "core", deck: "arithmetic", category: "算术", front: "百分点与百分比变化有什么区别？", back: "从40%到50%是增加10个百分点，相对原值增加25%。", source: "amc10-concept", verified: true },
  { id: "amc10-0084", level: "core", deck: "arithmetic", category: "算术", front: "单利模型是什么？", back: "本息和A=P(1+rt)；每期利息只按原本金计算。", source: "amc10-concept", verified: true },
  { id: "amc10-0085", level: "advance", deck: "arithmetic", category: "算术", front: "复利模型是什么？", back: "每期复利：期利率r、n期，A=P(1+r)^n；年名义利率r、每年复利m次、t年，A=P(1+r/m)^{mt}。两式r含义不同，n与t单位也不同。", source: "amc10-concept", verified: true },
  { id: "amc10-0086", level: "core", deck: "arithmetic", category: "算术", front: "利润与利润率如何计算？", back: "利润=售价-成本；利润率的分母必须按题意确认，通常相对成本。", source: "amc10-concept", verified: true },
  { id: "amc10-0087", level: "core", deck: "arithmetic", category: "算术", front: "流水行船的顺流、逆流速度是什么？", back: "船静水速度±水流速度。", source: "amc10-concept", verified: true },
  { id: "amc10-0088", level: "core", deck: "arithmetic", category: "算术", front: "环形跑道追及如何建模？", back: "同起点同向首次追上需弥补一圈，时间=圈长/速度差；起点相距g时时间=g/速度差；反向相遇用速度和。", source: "amc10-concept", verified: true },
  { id: "amc10-0089", level: "core", deck: "arithmetic", category: "算术", front: "中位数是什么？", back: "排序后居中的数；数据个数为偶数时取中间两数平均。", source: "amc10-concept", verified: true },
  { id: "amc10-0090", level: "core", deck: "arithmetic", category: "算术", front: "众数是什么？", back: "出现次数最多的数；可能没有或不止一个。", source: "amc10-concept", verified: true },
  { id: "amc10-0091", level: "core", deck: "arithmetic", category: "算术", front: "极差是什么？", back: "最大值减最小值。", source: "amc10-concept", verified: true },
  { id: "amc10-0092", level: "core", deck: "arithmetic", category: "算术", front: "加入一个新数据后平均数如何更新？", back: "先用旧平均数恢复旧总和，加新数后除以新个数。", source: "amc10-concept", verified: true },
  { id: "amc10-0093", level: "core", deck: "arithmetic", category: "数论", front: "一个区间内d的倍数个数如何求？", back: "1..N中为⌊N/d⌋；区间[L,R]中为⌊R/d⌋-⌊(L-1)/d⌋。", source: "amc10-concept", verified: true },
  { id: "amc10-0094", level: "core", deck: "arithmetic", category: "数论", front: "能同时被a,b整除等价于什么？", back: "能被lcm(a,b)整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0095", level: "core", deck: "arithmetic", category: "数论", front: "能被a或b整除的数量如何避免重复？", back: "两类相加，再减去lcm(a,b)的倍数数量。", source: "amc10-concept", verified: true },
  { id: "amc10-0096", level: "core", deck: "arithmetic", category: "数论", front: "被6整除的判定是什么？", back: "同时被2和3整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0097", level: "core", deck: "arithmetic", category: "数论", front: "被12整除的判定是什么？", back: "同时被3和4整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0098", level: "core", deck: "arithmetic", category: "数论", front: "有限小数的最简分母有什么特征？", back: "质因数只能有2和5。", source: "amc10-concept", verified: true },
  { id: "amc10-0099", level: "advance", deck: "arithmetic", category: "数论", front: "循环小数如何转成分数？", back: "设变量后乘适当的10次幂，使循环部分对齐相减。", source: "amc10-concept", verified: true },
  { id: "amc10-0100", level: "core", deck: "arithmetic", category: "数论", front: "有理数与无理数的根式识别是什么？", back: "整数n≥0的√n仅在n为完全平方时是整数/有理数。", source: "amc10-concept", verified: true },
  { id: "amc10-0101", level: "advance", deck: "arithmetic", category: "数论", front: "平方自由部分是什么？", back: "从质因数分解中去掉所有偶数次幂后剩余的乘积；用于合并和比较根式。", source: "amc10-concept", verified: true },
  { id: "amc10-0102", level: "advance", deck: "arithmetic", category: "数论", front: "⌊√n⌋=k等价于什么？", back: "k²≤n<(k+1)²。", source: "amc10-concept", verified: true },
  { id: "amc10-0103", level: "advance", deck: "arithmetic", category: "数论", front: "Fermat小定理是什么？", back: "质数p且p∤a时，a^{p-1}≡1 (mod p)。", source: "amc10-concept", verified: true },
  { id: "amc10-0104", level: "advance", deck: "arithmetic", category: "数论", front: "Euler定理是什么？", back: "gcd(a,n)=1时，a^{φ(n)}≡1 (mod n)。", source: "amc10-concept", verified: true },
  { id: "amc10-0105", level: "advance", deck: "arithmetic", category: "数论", front: "Euler函数φ(n)表示什么？", back: "1..n中与n互质的整数个数；若n=∏p_i^{a_i}，则φ(n)=n∏(1-1/p_i)。", source: "amc10-concept", verified: true },
  { id: "amc10-0106", level: "advance", deck: "arithmetic", category: "数论", front: "中国剩余思想何时有唯一周期解？", back: "模数两两互质时，联立同余在模数乘积意义下有唯一解。", source: "amc10-concept", verified: true },
  { id: "amc10-0107", level: "advance", deck: "arithmetic", category: "数论", front: "为什么使用Fermat/Euler前必须检查互质？", back: "底数被模数的质因子整除时，指数降周期结论可能失效。", source: "amc10-concept", verified: true },
  { id: "amc10-0108", level: "advance", deck: "arithmetic", category: "数论", front: "p进赋值v_p(n)是什么？", back: "质数p在n的质因数分解中的指数；乘法相加、整除比较指数。", source: "amc10-concept", verified: true },
  { id: "amc10-0109", level: "advance", deck: "arithmetic", category: "数论", front: "整数多项式输入同余时输出有什么关系？", back: "若a≡b (mod m)，则整系数多项式满足P(a)≡P(b) (mod m)。", source: "amc10-concept", verified: true },
  { id: "amc10-0110", level: "advance", deck: "arithmetic", category: "数论", front: "随机选一个正约数时如何描述约数？", back: "把每个质因数指数在0..a_i间选择；所有约数等可能时指数向量等可能。", source: "amc10-concept", verified: true },
  { id: "amc10-0111", level: "core", deck: "algebra", category: "代数", front: "解方程前为什么要写定义域？", back: "防止分母为0、偶次根号内为负及其他无意义值。", source: "amc10-concept", verified: true },
  { id: "amc10-0112", level: "core", deck: "algebra", category: "代数", front: "分式方程的标准流程是什么？", back: "写限制→乘最小公分母→解整式方程→验根。", source: "amc10-concept", verified: true },
  { id: "amc10-0113", level: "core", deck: "algebra", category: "代数", front: "根式方程为什么必须验根？", back: "平方可能引入增根。", source: "amc10-concept", verified: true },
  { id: "amc10-0114", level: "core", deck: "algebra", category: "代数", front: "二元一次方程组常用方法是什么？", back: "代入、消元，或用和差结构直接处理。", source: "amc10-concept", verified: true },
  { id: "amc10-0115", level: "core", deck: "algebra", category: "代数", front: "什么时候适合设总量为方便数字？", back: "只给比例或百分比且答案对尺度不敏感时。", source: "amc10-concept", verified: true },
  { id: "amc10-0116", level: "core", deck: "algebra", category: "代数", front: "代数换元的目标是什么？", back: "把重复结构视为一个变量，降低次数或减少项数。", source: "amc10-concept", verified: true },
  { id: "amc10-0117", level: "core", deck: "algebra", category: "代数", front: "对称式中常用的换元是什么？", back: "s=x+y,p=xy。", source: "amc10-concept", verified: true },
  { id: "amc10-0118", level: "core", deck: "algebra", category: "代数", front: "x²+y²如何用s=x+y,p=xy表示？", back: "s²-2p。", source: "amc10-concept", verified: true },
  { id: "amc10-0119", level: "core", deck: "algebra", category: "代数", front: "x³+y³如何表示？", back: "(x+y)³-3xy(x+y)=s³-3ps。", source: "amc10-concept", verified: true },
  { id: "amc10-0120", level: "core", deck: "algebra", category: "代数", front: "1/x+1/y如何合并？", back: "(x+y)/(xy)，前提xy≠0。", source: "amc10-concept", verified: true },
  { id: "amc10-0121", level: "core", deck: "algebra", category: "代数", front: "绝对值方程|x|=a如何解？", back: "a<0无解；a=0有x=0；a>0有x=±a。", source: "amc10-concept", verified: true },
  { id: "amc10-0122", level: "core", deck: "algebra", category: "代数", front: "|x-a|的几何意义是什么？", back: "数轴上x到a的距离。", source: "amc10-concept", verified: true },
  { id: "amc10-0123", level: "core", deck: "algebra", category: "代数", front: "解多个绝对值表达式的可靠方法是什么？", back: "按所有临界点分区间，去绝对值后逐段验范围。", source: "amc10-concept", verified: true },
  { id: "amc10-0124", level: "core", deck: "algebra", category: "代数", front: "取整函数⌊x⌋=n等价于什么？", back: "n≤x<n+1（n∈Z）。", source: "amc10-concept", verified: true },
  { id: "amc10-0125", level: "core", deck: "algebra", category: "代数", front: "上取整⌈x⌉=n等价于什么？", back: "n-1<x≤n（n∈Z）。", source: "amc10-concept", verified: true },
  { id: "amc10-0126", level: "advance", deck: "algebra", category: "代数", front: "含⌊x⌋方程为何要分整数部分和小数部分？", back: "写x=n+r，其中n∈Z,0≤r<1可固定跳变位置。", source: "amc10-concept", verified: true },
  { id: "amc10-0127", level: "core", deck: "algebra", category: "代数", front: "一元二次方程求根公式是什么？", back: "x=(-b±√(b²-4ac))/(2a)，a≠0。", source: "amc10-concept", verified: true },
  { id: "amc10-0128", level: "core", deck: "algebra", category: "代数", front: "判别式是什么？", back: "Δ=b²-4ac；决定实根个数。", source: "amc10-concept", verified: true },
  { id: "amc10-0129", level: "core", deck: "algebra", category: "代数", front: "二次方程有两个、一个、无实根的条件是什么？", back: "Δ>0,Δ=0,Δ<0。", source: "amc10-concept", verified: true },
  { id: "amc10-0130", level: "core", deck: "algebra", category: "代数", front: "韦达定理是什么？", back: "若根为r,s，则r+s=-b/a,rs=c/a。", source: "amc10-concept", verified: true },
  { id: "amc10-0131", level: "core", deck: "algebra", category: "代数", front: "已知根r,s的首一二次多项式是什么？", back: "(x-r)(x-s)=x²-(r+s)x+rs。", source: "amc10-concept", verified: true },
  { id: "amc10-0132", level: "core", deck: "algebra", category: "代数", front: "二次函数ax²+bx+c的对称轴是什么？", back: "x=-b/(2a)。", source: "amc10-concept", verified: true },
  { id: "amc10-0133", level: "core", deck: "algebra", category: "代数", front: "二次函数顶点纵坐标如何求？", back: "代入x=-b/(2a)，或配方。", source: "amc10-concept", verified: true },
  { id: "amc10-0134", level: "core", deck: "algebra", category: "代数", front: "配方的基本形式是什么？", back: "x²+bx=(x+b/2)²-b²/4。", source: "amc10-concept", verified: true },
  { id: "amc10-0135", level: "core", deck: "algebra", category: "代数", front: "二次函数最大/最小值由什么决定？", back: "开口方向和顶点；a>0有最小值，a<0有最大值。", source: "amc10-concept", verified: true },
  { id: "amc10-0136", level: "advance", deck: "algebra", category: "代数", front: "整系数二次方程何时有整数根？", back: "判别式需为完全平方，且求根公式分子能被2a整除。", source: "amc10-concept", verified: true },
  { id: "amc10-0137", level: "core", deck: "algebra", category: "代数", front: "因式定理是什么？", back: "P(r)=0当且仅当x-r是P(x)的因式。", source: "amc10-concept", verified: true },
  { id: "amc10-0138", level: "core", deck: "algebra", category: "代数", front: "余式定理是什么？", back: "P(x)除以x-r的余数为P(r)。", source: "amc10-concept", verified: true },
  { id: "amc10-0139", level: "advance", deck: "algebra", category: "代数", front: "除以二次式时余式长什么样？", back: "次数低于2，即ax+b。", source: "amc10-concept", verified: true },
  { id: "amc10-0140", level: "advance", deck: "algebra", category: "代数", front: "多项式恒等式如何确定未知系数？", back: "展开比较系数，或代入足够多个方便值。", source: "amc10-concept", verified: true },
  { id: "amc10-0141", level: "advance", deck: "algebra", category: "代数", front: "多项式整值题常用什么技巧？", back: "相邻输入作差、模因式、余式定理或整数根限制。", source: "amc10-concept", verified: true },
  { id: "amc10-0142", level: "core", deck: "algebra", category: "代数", front: "同底数幂相乘规则是什么？", back: "a^m a^n=a^{m+n}。", source: "amc10-concept", verified: true },
  { id: "amc10-0143", level: "core", deck: "algebra", category: "代数", front: "幂的幂规则是什么？", back: "(a^m)^n=a^{mn}（需a>0，或m、n都是整数）。", source: "amc10-concept", verified: true },
  { id: "amc10-0144", level: "core", deck: "algebra", category: "代数", front: "负指数是什么意思？", back: "a^{-n}=1/a^n，a≠0。", source: "amc10-concept", verified: true },
  { id: "amc10-0145", level: "core", deck: "algebra", category: "代数", front: "零指数规则是什么？", back: "a^0=1，a≠0。", source: "amc10-concept", verified: true },
  { id: "amc10-0146", level: "core", deck: "algebra", category: "代数", front: "分数指数如何解释？", back: "a^{m/n}=ⁿ√(a^m)，需a≥0（或m/n已约简且n为奇数）。", source: "amc10-concept", verified: true },
  { id: "amc10-0147", level: "core", deck: "algebra", category: "代数", front: "√(a²)等于什么？", back: "|a|，不是总等于a。", source: "amc10-concept", verified: true },
  { id: "amc10-0148", level: "core", deck: "algebra", category: "代数", front: "根式相加何时能合并？", back: "化为相同根式因子后才可合并系数。", source: "amc10-concept", verified: true },
  { id: "amc10-0149", level: "core", deck: "algebra", category: "代数", front: "如何有理化1/(√a+√b)？", back: "乘共轭√a-√b。", source: "amc10-concept", verified: true },
  { id: "amc10-0150", level: "core", deck: "algebra", category: "代数", front: "分式拆项的常见望远镜结构是什么？", back: "1/[n(n+1)]=1/n-1/(n+1)。", source: "amc10-concept", verified: true },
  { id: "amc10-0151", level: "advance", deck: "algebra", category: "代数", front: "1/[(n+a)(n+b)]如何拆？", back: "写成1/(b-a) · (1/(n+a)-1/(n+b))，需b≠a。", source: "amc10-concept", verified: true },
  { id: "amc10-0152", level: "core", deck: "algebra", category: "代数", front: "指数方程首选什么方法？", back: "尽量化成相同底数，再比较指数。", source: "amc10-concept", verified: true },
  { id: "amc10-0153", level: "advance", deck: "algebra", category: "代数", front: "根式和为单个根式时应检查什么？", back: "平方后交叉项是否为整数/同类根式，并验原式正负。", source: "amc10-concept", verified: true },
  { id: "amc10-0154", level: "core", deck: "algebra", category: "函数", front: "函数的定义是什么？", back: "每个允许输入对应唯一输出。", source: "amc10-concept", verified: true },
  { id: "amc10-0155", level: "core", deck: "algebra", category: "函数", front: "定义域是什么？", back: "所有允许输入的集合。", source: "amc10-concept", verified: true },
  { id: "amc10-0156", level: "core", deck: "algebra", category: "函数", front: "值域是什么？", back: "所有可能输出的集合。", source: "amc10-concept", verified: true },
  { id: "amc10-0157", level: "core", deck: "algebra", category: "函数", front: "f(a)是什么意思？", back: "把输入a代入函数规则；不是f·a。", source: "amc10-concept", verified: true },
  { id: "amc10-0158", level: "core", deck: "algebra", category: "函数", front: "复合函数f(g(x))如何计算？", back: "先算内层g(x)，再把结果输入f。", source: "amc10-concept", verified: true },
  { id: "amc10-0159", level: "core", deck: "algebra", category: "函数", front: "反函数存在的关键条件是什么？", back: "在所讨论定义域上一一对应。", source: "amc10-concept", verified: true },
  { id: "amc10-0160", level: "core", deck: "algebra", category: "函数", front: "图像y=f(x)+k如何移动？", back: "竖直上移k；k<0则下移。", source: "amc10-concept", verified: true },
  { id: "amc10-0161", level: "core", deck: "algebra", category: "函数", front: "图像y=f(x-h)如何移动？", back: "水平右移h；括号内方向相反。", source: "amc10-concept", verified: true },
  { id: "amc10-0162", level: "core", deck: "algebra", category: "函数", front: "y=-f(x)和y=f(-x)分别是什么反射？", back: "前者关于x轴，后者关于y轴。", source: "amc10-concept", verified: true },
  { id: "amc10-0163", level: "core", deck: "algebra", category: "函数", front: "偶函数的判定是什么？", back: "f(-x)=f(x)，图像关于y轴对称。", source: "amc10-concept", verified: true },
  { id: "amc10-0164", level: "core", deck: "algebra", category: "函数", front: "奇函数的判定是什么？", back: "f(-x)=-f(x)，图像关于原点中心对称。", source: "amc10-concept", verified: true },
  { id: "amc10-0165", level: "core", deck: "algebra", category: "函数", front: "两图像交点如何求？", back: "联立输出，即解f(x)=g(x)。", source: "amc10-concept", verified: true },
  { id: "amc10-0166", level: "advance", deck: "algebra", category: "函数", front: "函数迭代是什么意思？", back: "f^{(n)}(x)表示重复复合，不是通常意义的[f(x)]^n。", source: "amc10-concept", verified: true },
  { id: "amc10-0167", level: "advance", deck: "algebra", category: "函数", front: "分段函数的关键检查是什么？", back: "输入属于哪一段，以及端点等号归属。", source: "amc10-concept", verified: true },
  { id: "amc10-0168", level: "advance", deck: "algebra", category: "函数", front: "图像变换是否可交换？", back: "通常不可；必须按复合顺序追踪一个一般点。", source: "amc10-concept", verified: true },
  { id: "amc10-0169", level: "core", deck: "algebra", category: "数列", front: "等差数列通项是什么？", back: "a_n=a_1+(n-1)d。", source: "amc10-concept", verified: true },
  { id: "amc10-0170", level: "core", deck: "algebra", category: "数列", front: "等差数列前n项和是什么？", back: "S_n=n(a_1+a_n)/2=n[2a_1+(n-1)d]/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0171", level: "core", deck: "algebra", category: "数列", front: "等比数列通项是什么？", back: "a_n=a_1r^{n-1}。", source: "amc10-concept", verified: true },
  { id: "amc10-0172", level: "core", deck: "algebra", category: "数列", front: "等比数列前n项和是什么？", back: "S_n=a_1(1-r^n)/(1-r)，r≠1。", source: "amc10-concept", verified: true },
  { id: "amc10-0173", level: "core", deck: "algebra", category: "数列", front: "无穷等比级数何时收敛？", back: "|r|<1，和为a_1/(1-r)。", source: "amc10-concept", verified: true },
  { id: "amc10-0174", level: "core", deck: "algebra", category: "数列", front: "递推数列第一步应做什么？", back: "列前若干项，寻找周期、单调、奇偶或不变量。", source: "amc10-concept", verified: true },
  { id: "amc10-0175", level: "core", deck: "algebra", category: "数列", front: "索引最常见错误是什么？", back: "把第n项误写为经历n次变化；通常从a_1到a_n有n-1步。", source: "amc10-concept", verified: true },
  { id: "amc10-0176", level: "advance", deck: "algebra", category: "数列", front: "一阶线性递推a_{n+1}=ra_n+c如何找平衡点？", back: "解L=rL+c（需r≠1，r=1时退化为等差），再研究a_n-L的等比变化。", source: "amc10-concept", verified: true },
  { id: "amc10-0177", level: "advance", deck: "algebra", category: "数列", front: "周期递推如何求巨大下标？", back: "确定完整周期及起点，再对下标偏移取模。", source: "amc10-concept", verified: true },
  { id: "amc10-0178", level: "advance", deck: "algebra", category: "数列", front: "望远镜求和的识别信号是什么？", back: "相邻项分解后大部分正负抵消。", source: "amc10-concept", verified: true },
  { id: "amc10-0179", level: "advance", deck: "algebra", category: "数列", front: "Fibonacci型递推常用什么策略？", back: "列项、模周期、相邻项关系和部分和恒等式。", source: "amc10-concept", verified: true },
  { id: "amc10-0180", level: "core", deck: "algebra", category: "不等式", front: "乘除负数时不等号如何变化？", back: "方向反转。", source: "amc10-concept", verified: true },
  { id: "amc10-0181", level: "core", deck: "algebra", category: "不等式", front: "解有理不等式为什么不能直接乱乘分母？", back: "分母符号未知；应移到一边并作符号分析。", source: "amc10-concept", verified: true },
  { id: "amc10-0182", level: "core", deck: "algebra", category: "不等式", front: "三角不等式的数轴形式是什么？", back: "|x-a|+|x-b|≥|a-b|，等号当且仅当x在a与b之间（此时取最小值|a-b|）。", source: "amc10-concept", verified: true },
  { id: "amc10-0183", level: "core", deck: "algebra", category: "不等式", front: "二元AM-GM是什么？", back: "对x,y≥0，(x+y)/2≥√xy，等号在x=y。", source: "amc10-concept", verified: true },
  { id: "amc10-0184", level: "core", deck: "algebra", category: "不等式", front: "固定和时乘积何时最大？", back: "非负变量尽量相等时。", source: "amc10-concept", verified: true },
  { id: "amc10-0185", level: "core", deck: "algebra", category: "不等式", front: "固定积时和何时最小？", back: "正变量尽量相等时。", source: "amc10-concept", verified: true },
  { id: "amc10-0186", level: "advance", deck: "algebra", category: "不等式", front: "多元AM-GM是什么？", back: "非负数的算术平均不小于几何平均，等号在所有数相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0187", level: "advance", deck: "algebra", category: "不等式", front: "加权AM-GM的实战替代技巧是什么？", back: "按指数复制变量，如控制x²y就考虑x,x,y。", source: "amc10-concept", verified: true },
  { id: "amc10-0188", level: "core", deck: "algebra", category: "不等式", front: "Cauchy平方和形式是什么？", back: "(Σa_i²)(Σb_i²)≥(Σa_ib_i)²，等号当且仅当两组数成比例。", source: "amc10-concept", verified: true },
  { id: "amc10-0189", level: "core", deck: "algebra", category: "不等式", front: "n个数的平方和下界是什么？", back: "Σx_i²≥(Σx_i)²/n，等号在全部相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0190", level: "advance", deck: "algebra", category: "不等式", front: "Titu/Engel形式是什么？", back: "正分母下，Σa_i²/x_i≥(Σa_i)²/(Σx_i)，等号当且仅当a_i/x_i全相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0191", level: "core", deck: "algebra", category: "不等式", front: "1/x+1/y在x+y=S时的下界是什么？", back: "4/S，正数且x=y时取等。", source: "amc10-concept", verified: true },
  { id: "amc10-0192", level: "advance", deck: "algebra", category: "不等式", front: "QM-AM是什么？", back: "均方根不小于算术平均：√(Σa_i²/n)≥Σa_i/n（对任意实数成立），等号当且仅当所有数相等且公共值≥0；是Cauchy的直接结果。", source: "amc10-concept", verified: true },
  { id: "amc10-0193", level: "advance", deck: "algebra", category: "不等式", front: "线性式在固定平方和下如何最大化？", back: "用Cauchy；变量向系数向量成比例时取等。", source: "amc10-concept", verified: true },
  { id: "amc10-0194", level: "core", deck: "algebra", category: "不等式", front: "连续最值用于整数题后还要做什么？", back: "检查最邻近整数、实际因数对和同余可达性。", source: "amc10-concept", verified: true },
  { id: "amc10-0195", level: "core", deck: "algebra", category: "不等式", front: "整数平滑原则是什么？", back: "固定和时若两数相差至少2，把大数减1、小数加1通常增大乘积。", source: "amc10-concept", verified: true },
  { id: "amc10-0196", level: "core", deck: "algebra", category: "不等式", front: "最值题必须写出的两件事是什么？", back: "界限证明和达到该界的合法取等例子。", source: "amc10-concept", verified: true },
  { id: "amc10-0197", level: "advance", deck: "algebra", category: "不等式", front: "配方与AM-GM如何选择？", back: "二次式优先配方；非负固定和/积结构可用AM-GM。", source: "amc10-concept", verified: true },
  { id: "amc10-0198", level: "boundary", deck: "algebra", category: "不等式", front: "Jensen、Holder、Muirhead是否为AMC 10优先内容？", back: "不是；先熟练配方、AM-GM、Cauchy、Titu和整数可达性。", source: "amc10-concept", verified: true },
  { id: "amc10-0199", level: "core", deck: "algebra", category: "代数", front: "一元一次方程ax+b=c在a≠0时的解是什么？", back: "x=(c-b)/a。", source: "amc10-concept", verified: true },
  { id: "amc10-0200", level: "core", deck: "algebra", category: "代数", front: "恒等式、方程和条件式有什么区别？", back: "恒等式对定义域内所有值成立；方程只对解成立；条件式在给定条件下成立。", source: "amc10-concept", verified: true },
  { id: "amc10-0201", level: "core", deck: "algebra", category: "代数", front: "比例链a:b=c:d处理时最重要的条件是什么？", back: "分母非零，并明确哪些量共享同一比例因子。", source: "amc10-concept", verified: true },
  { id: "amc10-0202", level: "core", deck: "algebra", category: "代数", front: "立方和公式是什么？", back: "a³+b³=(a+b)(a²-ab+b²)。", source: "amc10-concept", verified: true },
  { id: "amc10-0203", level: "core", deck: "algebra", category: "代数", front: "立方差公式是什么？", back: "a³-b³=(a-b)(a²+ab+b²)。", source: "amc10-concept", verified: true },
  { id: "amc10-0204", level: "core", deck: "algebra", category: "代数", front: "分组因式分解的触发信号是什么？", back: "四项或多项能分组提取相同二项式因子。", source: "amc10-concept", verified: true },
  { id: "amc10-0205", level: "advance", deck: "algebra", category: "代数", front: "根的重数是什么意思？", back: "(x-r)^k整除多项式而更高次不整除时，r是k重根。", source: "amc10-concept", verified: true },
  { id: "amc10-0206", level: "advance", deck: "algebra", category: "代数", front: "多项式除以(x-a)(x-b)且a≠b时如何确定线性余式？", back: "设余式R(x)=mx+n，用R(a)=P(a),R(b)=P(b)求系数。", source: "amc10-concept", verified: true },
  { id: "amc10-0207", level: "advance", deck: "algebra", category: "代数", front: "首项系数不为1的有理根候选是什么？", back: "既约根p/q满足p|常数项,q|首项系数。", source: "amc10-concept", verified: true },
  { id: "amc10-0208", level: "core", deck: "algebra", category: "代数", front: "二项式定理是什么？", back: "(x+y)^n=Σ_{k=0}^n C(n,k)x^{n-k}y^k。", source: "amc10-concept", verified: true },
  { id: "amc10-0209", level: "core", deck: "algebra", category: "代数", front: "(x+y)^n中x^{n-k}y^k的系数是什么？", back: "C(n,k)。", source: "amc10-concept", verified: true },
  { id: "amc10-0210", level: "advance", deck: "algebra", category: "代数", front: "二项式展开的偶数项或奇数项系数和如何求？", back: "比较(1+1)^n与(1-1)^n，两者均为2^{n-1}（n≥1）。", source: "amc10-concept", verified: true },
  { id: "amc10-0211", level: "core", deck: "algebra", category: "不等式", front: "|x-a|<r和|x-a|≤r分别表示什么？", back: "分别是a-r<x<a+r与a-r≤x≤a+r。", source: "amc10-concept", verified: true },
  { id: "amc10-0212", level: "core", deck: "algebra", category: "不等式", front: "|x-a|>r表示什么？", back: "x<a-r或x>a+r，前提r≥0。", source: "amc10-concept", verified: true },
  { id: "amc10-0213", level: "core", deck: "algebra", category: "不等式", front: "二次不等式如何用符号表求解？", back: "找零点与不可取点，按区间判断因子符号并处理端点。", source: "amc10-concept", verified: true },
  { id: "amc10-0214", level: "advance", deck: "algebra", category: "不等式", front: "平方非负如何制造常用界？", back: "从(x-y)²≥0得到x²+y²≥2xy，或从(x-a)²≥0配方。", source: "amc10-concept", verified: true },
  { id: "amc10-0215", level: "advance", deck: "algebra", category: "不等式", front: "判别式如何用于参数最值？", back: "把条件写成关于某变量的二次方程；存在实解要求Δ≥0，边界常在Δ=0。", source: "amc10-concept", verified: true },
  { id: "amc10-0216", level: "advance", deck: "algebra", category: "不等式", front: "重排不等式的直观版本是什么？", back: "两个同向排序序列的对应乘积和最大，反向配对最小；极值在排序完全一致/完全相反时取到。", source: "amc10-concept", verified: true },
  { id: "amc10-0217", level: "advance", deck: "algebra", category: "不等式", front: "单调函数在闭区间上的最值通常在哪里检查？", back: "若能证明单调，只需检查端点。", source: "amc10-concept", verified: true },
  { id: "amc10-0218", level: "advance", deck: "algebra", category: "不等式", front: "凸二次函数在整数点上的最小值如何找？", back: "先找实数顶点，再检查其两侧最近整数。", source: "amc10-concept", verified: true },
  { id: "amc10-0219", level: "core", deck: "algebra", category: "函数", front: "线性函数y=mx+b中m,b分别表示什么？", back: "斜率和y轴截距。", source: "amc10-concept", verified: true },
  { id: "amc10-0220", level: "core", deck: "algebra", category: "函数", front: "函数的零点是什么？", back: "使f(x)=0的输入，即图像与x轴的交点横坐标。", source: "amc10-concept", verified: true },
  { id: "amc10-0221", level: "core", deck: "algebra", category: "函数", front: "反函数如何从方程求？", back: "写y=f(x)，交换x,y后解出y，并检查一一性与定义域。", source: "amc10-concept", verified: true },
  { id: "amc10-0222", level: "advance", deck: "algebra", category: "函数", front: "水平伸缩y=f(bx)如何理解？", back: "横坐标按1/|b|缩放；b<0还关于y轴反射。", source: "amc10-concept", verified: true },
  { id: "amc10-0223", level: "advance", deck: "algebra", category: "函数", front: "函数方程题的常用代入是什么？", back: "代0、1、相等变量、相反数或令内层表达式取特殊值。", source: "amc10-concept", verified: true },
  { id: "amc10-0224", level: "core", deck: "algebra", category: "统计", front: "平均数、中位数、众数分别反映什么？", back: "平均数用全部数值；中位数反映排序中心；众数反映最高频值。", source: "amc10-concept", verified: true },
  { id: "amc10-0225", level: "core", deck: "algebra", category: "统计", front: "哪个统计量最容易受极端值影响？", back: "平均数；中位数通常更稳健。", source: "amc10-concept", verified: true },
  { id: "amc10-0226", level: "core", deck: "algebra", category: "统计", front: "方差/离均差平方和为什么非负？", back: "每个(x_i-x̄)²≥0，总和至少为0且全相等时为0。", source: "amc10-concept", verified: true },
  { id: "amc10-0227", level: "core", deck: "algebra", category: "统计", front: "从频数表求平均数如何做？", back: "Σ(数值×频数)/总频数。", source: "amc10-concept", verified: true },
  { id: "amc10-0228", level: "core", deck: "algebra", category: "统计", front: "直方图与条形图的关键区别是什么？", back: "直方图表示数值区间且柱通常相连；条形图表示类别。", source: "amc10-concept", verified: true },
  { id: "amc10-0229", level: "advance", deck: "algebra", category: "数列", front: "混合等差等比数列如何识别？", back: "检查相邻差、相邻比、奇偶子序列或分块规则，不要强套单一模型。", source: "amc10-concept", verified: true },
  { id: "amc10-0230", level: "advance", deck: "algebra", category: "数列", front: "二维递推表常如何处理？", back: "从边界开始按规则填小表，寻找Pascal型加法、对称或路径计数解释。", source: "amc10-concept", verified: true },
  { id: "amc10-0231", level: "advance", deck: "algebra", category: "数列", front: "部分和S_n与通项有什么关系？", back: "a_n=S_n-S_{n-1}（n≥2），且a_1=S_1。", source: "amc10-concept", verified: true },
  { id: "amc10-0232", level: "core", deck: "geometry", category: "几何", front: "对顶角有什么关系？", back: "相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0233", level: "core", deck: "geometry", category: "几何", front: "一条直线上的邻补角和是多少？", back: "180°。", source: "amc10-concept", verified: true },
  { id: "amc10-0234", level: "core", deck: "geometry", category: "几何", front: "点周围一周角是多少？", back: "360°。", source: "amc10-concept", verified: true },
  { id: "amc10-0235", level: "core", deck: "geometry", category: "几何", front: "平行线被截时有哪些常用角关系？", back: "同位角相等、内错角相等、同旁内角互补。", source: "amc10-concept", verified: true },
  { id: "amc10-0236", level: "core", deck: "geometry", category: "几何", front: "三角形内角和是多少？", back: "180°。", source: "amc10-concept", verified: true },
  { id: "amc10-0237", level: "core", deck: "geometry", category: "几何", front: "三角形外角定理是什么？", back: "一个外角等于两个不相邻内角之和。", source: "amc10-concept", verified: true },
  { id: "amc10-0238", level: "core", deck: "geometry", category: "几何", front: "n边形内角和是多少？", back: "(n-2)·180°。", source: "amc10-concept", verified: true },
  { id: "amc10-0239", level: "core", deck: "geometry", category: "几何", front: "任意凸多边形外角和是多少？", back: "360°。", source: "amc10-concept", verified: true },
  { id: "amc10-0240", level: "core", deck: "geometry", category: "几何", front: "正n边形每个内角是多少？", back: "(n-2)180°/n。", source: "amc10-concept", verified: true },
  { id: "amc10-0241", level: "core", deck: "geometry", category: "几何", front: "正n边形每个外角/中心角是多少？", back: "360°/n。", source: "amc10-concept", verified: true },
  { id: "amc10-0242", level: "core", deck: "geometry", category: "几何", front: "三角形不等式是什么？", back: "任意两边之和严格大于第三边。", source: "amc10-concept", verified: true },
  { id: "amc10-0243", level: "core", deck: "geometry", category: "几何", front: "两边固定时第三边c的范围是什么？", back: "|a-b|<c<a+b。", source: "amc10-concept", verified: true },
  { id: "amc10-0244", level: "core", deck: "geometry", category: "几何", front: "等腰三角形的基本性质是什么？", back: "等边对等角；顶角平分线也是底边中线和高。", source: "amc10-concept", verified: true },
  { id: "amc10-0245", level: "core", deck: "geometry", category: "几何", front: "等边三角形的高和面积是什么？", back: "高√3s/2，面积√3s²/4。", source: "amc10-concept", verified: true },
  { id: "amc10-0246", level: "core", deck: "geometry", category: "几何", front: "三角形全等判定有哪些？", back: "SSS、SAS、ASA、AAS，以及直角三角形HL。", source: "amc10-concept", verified: true },
  { id: "amc10-0247", level: "core", deck: "geometry", category: "几何", front: "为什么SSA通常不能判全等？", back: "可能存在两个不同三角形满足条件。", source: "amc10-concept", verified: true },
  { id: "amc10-0248", level: "core", deck: "geometry", category: "几何", front: "三角形相似判定有哪些？", back: "AA（两角相等）、SAS（两边成比例且夹角相等）、SSS（三边成比例）。", source: "amc10-concept", verified: true },
  { id: "amc10-0249", level: "core", deck: "geometry", category: "几何", front: "相似比为k时周长比、面积比分别是什么？", back: "k和k²。", source: "amc10-concept", verified: true },
  { id: "amc10-0250", level: "core", deck: "geometry", category: "几何", front: "相似立体线性比为k时表面积比、体积比是什么？", back: "k²和k³。", source: "amc10-concept", verified: true },
  { id: "amc10-0251", level: "core", deck: "geometry", category: "几何", front: "三角形中位线定理是什么？", back: "连接两边中点的线段平行第三边且长度为其一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0252", level: "core", deck: "geometry", category: "几何", front: "三角形中线是什么？", back: "顶点连接对边中点的线段。", source: "amc10-concept", verified: true },
  { id: "amc10-0253", level: "core", deck: "geometry", category: "几何", front: "重心如何分中线？", back: "从顶点到重心与重心到边中点之比为2:1。", source: "amc10-concept", verified: true },
  { id: "amc10-0254", level: "core", deck: "geometry", category: "几何", front: "角平分线定理是什么？", back: "内角平分线把对边分成邻边长度之比。", source: "amc10-concept", verified: true },
  { id: "amc10-0255", level: "core", deck: "geometry", category: "几何", front: "高是什么？", back: "从顶点向对边所在直线作的垂线段。", source: "amc10-concept", verified: true },
  { id: "amc10-0256", level: "advance", deck: "geometry", category: "几何", front: "中线长度公式是什么？", back: "m_a²=(2b²+2c²-a²)/4。", source: "amc10-concept", verified: true },
  { id: "amc10-0257", level: "advance", deck: "geometry", category: "几何", front: "Stewart定理描述什么？", back: "在△ABC中，D在BC上，BD=m、DC=n（a=m+n），AD=d，则b²m+c²n=a(d²+mn)；只在直接代入能明显缩短时用。", source: "amc10-concept", verified: true },
  { id: "amc10-0258", level: "core", deck: "geometry", category: "几何", front: "三角形重心是什么？", back: "三条中线的交点。", source: "amc10-concept", verified: true },
  { id: "amc10-0259", level: "core", deck: "geometry", category: "几何", front: "三角形内心是什么？", back: "三条内角平分线的交点。", source: "amc10-concept", verified: true },
  { id: "amc10-0260", level: "core", deck: "geometry", category: "几何", front: "三角形外心是什么？", back: "三边垂直平分线的交点。", source: "amc10-concept", verified: true },
  { id: "amc10-0261", level: "core", deck: "geometry", category: "几何", front: "三角形垂心是什么？", back: "三条高所在直线的交点。", source: "amc10-concept", verified: true },
  { id: "amc10-0262", level: "core", deck: "geometry", category: "几何", front: "内心到三边的距离有什么性质？", back: "相等，等于内切圆半径。", source: "amc10-concept", verified: true },
  { id: "amc10-0263", level: "core", deck: "geometry", category: "几何", front: "外心到三个顶点的距离有什么性质？", back: "相等，等于外接圆半径。", source: "amc10-concept", verified: true },
  { id: "amc10-0264", level: "core", deck: "geometry", category: "几何", front: "直角三角形外心在哪里？", back: "斜边中点。", source: "amc10-concept", verified: true },
  { id: "amc10-0265", level: "core", deck: "geometry", category: "几何", front: "直角三角形斜边中点性质是什么？", back: "到三个顶点距离相等，均为斜边一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0266", level: "core", deck: "geometry", category: "几何", front: "三角形面积基本公式是什么？", back: "K=bh/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0267", level: "core", deck: "geometry", category: "几何", front: "同高三角形面积比是什么？", back: "底边长度比。", source: "amc10-concept", verified: true },
  { id: "amc10-0268", level: "core", deck: "geometry", category: "几何", front: "同底三角形面积比是什么？", back: "高之比。", source: "amc10-concept", verified: true },
  { id: "amc10-0269", level: "core", deck: "geometry", category: "几何", front: "平行线之间同底三角形的面积关系是什么？", back: "高相同，因此面积相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0270", level: "core", deck: "geometry", category: "几何", front: "勾股定理是什么？", back: "直角三角形两直角边平方和等于斜边平方。", source: "amc10-concept", verified: true },
  { id: "amc10-0271", level: "core", deck: "geometry", category: "几何", front: "勾股逆定理是什么？", back: "若最长边平方等于另两边平方和，则三角形为直角三角形。", source: "amc10-concept", verified: true },
  { id: "amc10-0272", level: "core", deck: "geometry", category: "几何", front: "常用勾股数组有哪些？", back: "3-4-5、5-12-13、7-24-25、8-15-17及其倍数。", source: "amc10-concept", verified: true },
  { id: "amc10-0273", level: "advance", deck: "geometry", category: "几何", front: "本原勾股数组参数式是什么？", back: "m²-n²,2mn,m²+n²，其中m>n>0、gcd(m,n)=1且m、n一奇一偶。", source: "amc10-concept", verified: true },
  { id: "amc10-0274", level: "core", deck: "geometry", category: "几何", front: "45-45-90三角形边比是什么？", back: "1:1:√2。", source: "amc10-concept", verified: true },
  { id: "amc10-0275", level: "core", deck: "geometry", category: "几何", front: "30-60-90三角形边比是什么？", back: "1:√3:2，依次对30°、60°、90°。", source: "amc10-concept", verified: true },
  { id: "amc10-0276", level: "core", deck: "geometry", category: "几何", front: "直角三角形面积还可如何写？", back: "两直角边乘积的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0277", level: "core", deck: "geometry", category: "几何", front: "Heron公式是什么？", back: "K=√[s(s-a)(s-b)(s-c)]，s=(a+b+c)/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0278", level: "advance", deck: "geometry", category: "几何", front: "三角形面积与内切圆半径的关系是什么？", back: "K=rs。", source: "amc10-concept", verified: true },
  { id: "amc10-0279", level: "advance", deck: "geometry", category: "几何", front: "三角形面积与外接圆半径的关系是什么？", back: "K=abc/(4R)；作为提高工具使用。", source: "amc10-concept", verified: true },
  { id: "amc10-0280", level: "core", deck: "geometry", category: "几何", front: "坐标平面两点距离公式是什么？", back: "√[(x₂-x₁)²+(y₂-y₁)²]。", source: "amc10-concept", verified: true },
  { id: "amc10-0281", level: "core", deck: "geometry", category: "几何", front: "中点公式是什么？", back: "((x₁+x₂)/2,(y₁+y₂)/2)。", source: "amc10-concept", verified: true },
  { id: "amc10-0282", level: "core", deck: "geometry", category: "几何", front: "斜率公式是什么？", back: "(y₂-y₁)/(x₂-x₁)，竖直线斜率不存在。", source: "amc10-concept", verified: true },
  { id: "amc10-0283", level: "core", deck: "geometry", category: "几何", front: "两条非竖直平行线斜率有什么关系？", back: "相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0284", level: "core", deck: "geometry", category: "几何", front: "两条非竖直互相垂直的直线斜率有什么关系？", back: "乘积为-1。", source: "amc10-concept", verified: true },
  { id: "amc10-0285", level: "advance", deck: "geometry", category: "几何", front: "坐标多边形面积如何求？", back: "可切割、补形，或使用鞋带公式并取绝对值的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0286", level: "core", deck: "geometry", category: "几何", front: "平行四边形有哪些性质？", back: "对边平行且相等、对角相等、邻角互补、对角线互相平分。", source: "amc10-concept", verified: true },
  { id: "amc10-0287", level: "core", deck: "geometry", category: "几何", front: "矩形有哪些额外性质？", back: "四角为直角，对角线相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0288", level: "core", deck: "geometry", category: "几何", front: "菱形有哪些额外性质？", back: "四边相等，对角线垂直且平分对角。", source: "amc10-concept", verified: true },
  { id: "amc10-0289", level: "core", deck: "geometry", category: "几何", front: "正方形兼具哪些性质？", back: "矩形与菱形的全部性质。", source: "amc10-concept", verified: true },
  { id: "amc10-0290", level: "core", deck: "geometry", category: "几何", front: "梯形中位线长度是什么？", back: "两底和的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0291", level: "core", deck: "geometry", category: "几何", front: "平行四边形面积是什么？", back: "底×高。", source: "amc10-concept", verified: true },
  { id: "amc10-0292", level: "core", deck: "geometry", category: "几何", front: "梯形面积是什么？", back: "(上底+下底)×高/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0293", level: "core", deck: "geometry", category: "几何", front: "菱形/风筝用对角线求面积的公式是什么？", back: "垂直对角线乘积的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0294", level: "core", deck: "geometry", category: "几何", front: "正n边形如何分割求面积？", back: "分成n个以中心为顶点的全等等腰三角形。", source: "amc10-concept", verified: true },
  { id: "amc10-0295", level: "advance", deck: "geometry", category: "几何", front: "正多边形面积与周长、边心距的关系是什么？", back: "K=(1/2)·周长·边心距。", source: "amc10-concept", verified: true },
  { id: "amc10-0296", level: "advance", deck: "geometry", category: "几何", front: "多边形对角线条数是多少？", back: "n(n-3)/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0297", level: "core", deck: "geometry", category: "圆", front: "圆周长和面积公式是什么？", back: "2πr和πr²。", source: "amc10-concept", verified: true },
  { id: "amc10-0298", level: "core", deck: "geometry", category: "圆", front: "弧长公式是什么？", back: "θ/360°·2πr。", source: "amc10-concept", verified: true },
  { id: "amc10-0299", level: "core", deck: "geometry", category: "圆", front: "扇形面积公式是什么？", back: "θ/360°·πr²。", source: "amc10-concept", verified: true },
  { id: "amc10-0300", level: "core", deck: "geometry", category: "圆", front: "同弧所对圆周角与圆心角关系是什么？", back: "圆周角是圆心角的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0301", level: "core", deck: "geometry", category: "圆", front: "直径所对圆周角是多少？", back: "90°。", source: "amc10-concept", verified: true },
  { id: "amc10-0302", level: "core", deck: "geometry", category: "圆", front: "同弧所对圆周角有什么关系？", back: "相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0303", level: "core", deck: "geometry", category: "圆", front: "圆内接四边形对角关系是什么？", back: "对角互补。", source: "amc10-concept", verified: true },
  { id: "amc10-0304", level: "core", deck: "geometry", category: "圆", front: "半径与切线在切点处有什么关系？", back: "垂直。", source: "amc10-concept", verified: true },
  { id: "amc10-0305", level: "core", deck: "geometry", category: "圆", front: "同一外点引圆的两条切线段有什么关系？", back: "长度相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0306", level: "core", deck: "geometry", category: "圆", front: "弦的垂直平分线经过哪里？", back: "圆心。", source: "amc10-concept", verified: true },
  { id: "amc10-0307", level: "core", deck: "geometry", category: "圆", front: "圆心到弦的垂线有什么性质？", back: "平分该弦。", source: "amc10-concept", verified: true },
  { id: "amc10-0308", level: "core", deck: "geometry", category: "圆", front: "两弦相交的幂定理是什么？", back: "PA·PB=PC·PD。", source: "amc10-concept", verified: true },
  { id: "amc10-0309", level: "core", deck: "geometry", category: "圆", front: "割线—割线幂定理是什么？", back: "外部段×整条割线在两条割线上相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0310", level: "core", deck: "geometry", category: "圆", front: "切线—割线幂定理是什么？", back: "切线长²=外部段×整条割线。", source: "amc10-concept", verified: true },
  { id: "amc10-0311", level: "advance", deck: "geometry", category: "圆", front: "相交弦形成的内部角如何求？", back: "角度为所截两弧度数和的一半。", source: "amc10-concept", verified: true },
  { id: "amc10-0312", level: "advance", deck: "geometry", category: "圆", front: "圆外两割线/切线形成的角如何求？", back: "角度=(大弧−小弧)/2。", source: "amc10-concept", verified: true },
  { id: "amc10-0313", level: "core", deck: "geometry", category: "圆", front: "两圆外切时圆心距是什么？", back: "两半径之和。", source: "amc10-concept", verified: true },
  { id: "amc10-0314", level: "core", deck: "geometry", category: "圆", front: "两圆内切时圆心距是什么？", back: "两半径之差的绝对值。", source: "amc10-concept", verified: true },
  { id: "amc10-0315", level: "core", deck: "geometry", category: "圆", front: "相切圆题为什么先连圆心与切点？", back: "切点和圆心共线或形成半径垂线，可制造直角与确定距离。", source: "amc10-concept", verified: true },
  { id: "amc10-0316", level: "advance", deck: "geometry", category: "圆", front: "弓形面积如何求？", back: "劣弧弓形=扇形面积−对应三角形面积；优弧弓形=扇形面积+对应三角形面积。", source: "amc10-concept", verified: true },
  { id: "amc10-0317", level: "advance", deck: "geometry", category: "圆", front: "圆内接正多边形常用什么分割？", back: "从圆心连接顶点形成全等等腰三角形。", source: "amc10-concept", verified: true },
  { id: "amc10-0318", level: "core", deck: "geometry", category: "变换", front: "平移保持哪些量？", back: "长度、角度、面积和方向。", source: "amc10-concept", verified: true },
  { id: "amc10-0319", level: "core", deck: "geometry", category: "变换", front: "旋转保持哪些量？", back: "长度、角度、面积；点到旋转中心距离不变。", source: "amc10-concept", verified: true },
  { id: "amc10-0320", level: "core", deck: "geometry", category: "变换", front: "反射保持哪些量？", back: "长度、角度、面积，但改变方向性。", source: "amc10-concept", verified: true },
  { id: "amc10-0321", level: "core", deck: "geometry", category: "变换", front: "位似倍率为k时长度和面积如何变化？", back: "长度乘|k|，面积乘k²。", source: "amc10-concept", verified: true },
  { id: "amc10-0322", level: "core", deck: "geometry", category: "变换", front: "关于x轴反射的坐标规则是什么？", back: "(x,y)→(x,-y)。", source: "amc10-concept", verified: true },
  { id: "amc10-0323", level: "core", deck: "geometry", category: "变换", front: "关于y轴反射的坐标规则是什么？", back: "(x,y)→(-x,y)。", source: "amc10-concept", verified: true },
  { id: "amc10-0324", level: "core", deck: "geometry", category: "变换", front: "关于原点旋转180°的规则是什么？", back: "(x,y)→(-x,-y)。", source: "amc10-concept", verified: true },
  { id: "amc10-0325", level: "core", deck: "geometry", category: "变换", front: "绕原点逆时针90°的规则是什么？", back: "(x,y)→(-y,x)。", source: "amc10-concept", verified: true },
  { id: "amc10-0326", level: "core", deck: "geometry", category: "轨迹", front: "到两定点距离相等的点的轨迹是什么？", back: "两点连线的垂直平分线。", source: "amc10-concept", verified: true },
  { id: "amc10-0327", level: "core", deck: "geometry", category: "轨迹", front: "到两相交直线距离相等的点的轨迹是什么？", back: "两条角平分线。", source: "amc10-concept", verified: true },
  { id: "amc10-0328", level: "core", deck: "geometry", category: "轨迹", front: "到定点距离固定的轨迹是什么？", back: "以该点为圆心的圆。", source: "amc10-concept", verified: true },
  { id: "amc10-0329", level: "core", deck: "geometry", category: "路径", front: "折线路径最短题常用什么方法？", back: "反射端点，把折线拉直为直线。", source: "amc10-concept", verified: true },
  { id: "amc10-0330", level: "advance", deck: "geometry", category: "路径", front: "圆滚动无滑动时移动距离如何联系转角？", back: "轮心平移距离等于滚过弧长rθ。", source: "amc10-concept", verified: true },
  { id: "amc10-0331", level: "advance", deck: "geometry", category: "几何", front: "几何题何时适合坐标化？", back: "有直角、平行、规则图形或距离条件，且能选出简洁坐标时。", source: "amc10-concept", verified: true },
  { id: "amc10-0332", level: "core", deck: "geometry", category: "立体", front: "长方体体积是什么？", back: "lwh。", source: "amc10-concept", verified: true },
  { id: "amc10-0333", level: "core", deck: "geometry", category: "立体", front: "长方体表面积是什么？", back: "2(lw+lh+wh)。", source: "amc10-concept", verified: true },
  { id: "amc10-0334", level: "core", deck: "geometry", category: "立体", front: "棱柱体积是什么？", back: "底面积×高。", source: "amc10-concept", verified: true },
  { id: "amc10-0335", level: "core", deck: "geometry", category: "立体", front: "棱锥体积是什么？", back: "底面积×高/3。", source: "amc10-concept", verified: true },
  { id: "amc10-0336", level: "core", deck: "geometry", category: "立体", front: "圆柱体积是什么？", back: "πr²h。", source: "amc10-concept", verified: true },
  { id: "amc10-0337", level: "core", deck: "geometry", category: "立体", front: "圆柱侧面积是什么？", back: "2πrh。", source: "amc10-concept", verified: true },
  { id: "amc10-0338", level: "core", deck: "geometry", category: "立体", front: "圆锥体积是什么？", back: "πr²h/3。", source: "amc10-concept", verified: true },
  { id: "amc10-0339", level: "core", deck: "geometry", category: "立体", front: "圆锥侧面积是什么？", back: "πrℓ，其中ℓ为母线。", source: "amc10-concept", verified: true },
  { id: "amc10-0340", level: "core", deck: "geometry", category: "立体", front: "球体积是什么？", back: "4πr³/3。", source: "amc10-concept", verified: true },
  { id: "amc10-0341", level: "core", deck: "geometry", category: "立体", front: "球表面积是什么？", back: "4πr²。", source: "amc10-concept", verified: true },
  { id: "amc10-0342", level: "core", deck: "geometry", category: "立体", front: "体积守恒题的核心方程是什么？", back: "变化前后材料/液体总体积相等，注意溢出和空隙。", source: "amc10-concept", verified: true },
  { id: "amc10-0343", level: "core", deck: "geometry", category: "立体", front: "相似立体体积比如何由长度比得到？", back: "长度比的三次方。", source: "amc10-concept", verified: true },
  { id: "amc10-0344", level: "core", deck: "geometry", category: "立体", front: "长方体空间对角线是多少？", back: "√(l²+w²+h²)。", source: "amc10-concept", verified: true },
  { id: "amc10-0345", level: "core", deck: "geometry", category: "立体", front: "Euler多面体公式是什么？", back: "对凸多面体，V-E+F=2。", source: "amc10-concept", verified: true },
  { id: "amc10-0346", level: "advance", deck: "geometry", category: "立体", front: "双计数多面体边的方法是什么？", back: "各面边数总和等于2E；各顶点度数总和也等于2E。", source: "amc10-concept", verified: true },
  { id: "amc10-0347", level: "advance", deck: "geometry", category: "立体", front: "截面题的第一步是什么？", back: "确认截面与哪些棱/面相交，再用相似或坐标求边长。", source: "amc10-concept", verified: true },
  { id: "amc10-0348", level: "advance", deck: "geometry", category: "立体", front: "展开图最短路径如何处理？", back: "展开相邻表面，把表面折线路径变成平面直线。", source: "amc10-concept", verified: true },
  { id: "amc10-0349", level: "advance", deck: "geometry", category: "立体", front: "容器液面题需要警惕什么？", back: "容器形状变化时横截面积可能不恒定，不能总用高度成比例。", source: "amc10-concept", verified: true },
  { id: "amc10-0350", level: "boundary", deck: "geometry", category: "几何", front: "AMC 10是否要求三角函数？", back: "官方范围排除三角学；特殊角用特殊三角形和几何关系处理。", source: "amc10-concept", verified: true },
  { id: "amc10-0351", level: "core", deck: "geometry", category: "坐标", front: "直线的斜截式是什么？", back: "y=mx+b，适用于非竖直线。", source: "amc10-concept", verified: true },
  { id: "amc10-0352", level: "core", deck: "geometry", category: "坐标", front: "过点(x₁,y₁)、斜率为m的点斜式是什么？", back: "y-y₁=m(x-x₁)。", source: "amc10-concept", verified: true },
  { id: "amc10-0353", level: "core", deck: "geometry", category: "坐标", front: "竖直线和水平线方程分别是什么？", back: "x=c与y=c。", source: "amc10-concept", verified: true },
  { id: "amc10-0354", level: "core", deck: "geometry", category: "坐标", front: "圆的标准方程是什么？", back: "(x-h)²+(y-k)²=r²，圆心(h,k)、半径r。", source: "amc10-concept", verified: true },
  { id: "amc10-0355", level: "core", deck: "geometry", category: "坐标", front: "点到水平/竖直直线的距离如何求？", back: "坐标差的绝对值。", source: "amc10-concept", verified: true },
  { id: "amc10-0356", level: "advance", deck: "geometry", category: "坐标", front: "点到一般直线Ax+By+C=0的距离是什么？", back: "|Ax₀+By₀+C|/√(A²+B²)。", source: "amc10-concept", verified: true },
  { id: "amc10-0357", level: "core", deck: "geometry", category: "坐标", front: "两向量的坐标加法表达什么？", back: "位移逐坐标相加；可处理连续平移和路径终点。", source: "amc10-concept", verified: true },
  { id: "amc10-0358", level: "advance", deck: "geometry", category: "坐标", front: "两向量垂直的坐标判定是什么？", back: "点积u₁v₁+u₂v₂=0。", source: "amc10-concept", verified: true },
  { id: "amc10-0359", level: "advance", deck: "geometry", category: "格点", front: "Pick定理是什么？", back: "简单格点多边形面积A=I+B/2-1，I为内部格点数、B为边界格点数。", source: "amc10-concept", verified: true },
  { id: "amc10-0360", level: "advance", deck: "geometry", category: "格点", front: "线段两端为格点时边界格点间隔数是什么？", back: "gcd(|Δx|,|Δy|)；含两端的格点数再加1。", source: "amc10-concept", verified: true },
  { id: "amc10-0361", level: "advance", deck: "geometry", category: "几何", front: "共圆的常用判定有哪些？", back: "对角互补；或同弦等角且两点在弦同侧（异侧时两角互补）。", source: "amc10-concept", verified: true },
  { id: "amc10-0362", level: "advance", deck: "geometry", category: "圆", front: "切线—弦定理是什么？", back: "切线与弦所成角等于该弦在圆周另一侧所对的圆周角。", source: "amc10-concept", verified: true },
  { id: "amc10-0363", level: "advance", deck: "geometry", category: "圆", front: "Ptolemy定理是什么？", back: "圆内接四边形两对角线乘积等于两组对边乘积之和。", source: "amc10-concept", verified: true },
  { id: "amc10-0364", level: "advance", deck: "geometry", category: "圆", front: "两圆公共弦与圆心连线有什么关系？", back: "公共弦垂直于两圆圆心连线。", source: "amc10-concept", verified: true },
  { id: "amc10-0365", level: "advance", deck: "geometry", category: "圆", front: "根轴思想是什么？", back: "对两圆幂相等的点构成一条直线，包含两圆交点的公共弦所在直线。", source: "amc10-concept", verified: true },
  { id: "amc10-0366", level: "advance", deck: "geometry", category: "三角形", front: "Ceva定理的用途是什么？", back: "判定三条塞瓦线共点：有向长度比乘积=1（含三线平行的情形）；用无向长度比时必须限定三点都在三边线段上。", source: "amc10-concept", verified: true },
  { id: "amc10-0367", level: "advance", deck: "geometry", category: "三角形", front: "Menelaus定理的用途是什么？", back: "判定一条直线与三角形三边或延长线的三个交点共线；需谨慎使用有向长度。", source: "amc10-concept", verified: true },
  { id: "amc10-0368", level: "advance", deck: "geometry", category: "三角形", front: "中线为何把三角形面积二等分？", back: "两个子三角形共享同一高且底边相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0369", level: "advance", deck: "geometry", category: "几何", front: "面积比追踪的优先规则是什么？", back: "先找同高、同底，再找相似比平方，最后才计算具体长度。", source: "amc10-concept", verified: true },
  { id: "amc10-0370", level: "advance", deck: "geometry", category: "正多边形", front: "正多边形能铺满某顶点的角度条件是什么？", back: "汇聚在该点的内角和必须为360°。", source: "amc10-concept", verified: true },
  { id: "amc10-0371", level: "advance", deck: "geometry", category: "变换", front: "两次平行线反射的复合是什么？", back: "沿垂线方向平移，距离为两线间距的2倍。", source: "amc10-concept", verified: true },
  { id: "amc10-0372", level: "advance", deck: "geometry", category: "变换", front: "两次相交线反射的复合是什么？", back: "绕交点旋转，旋转角为两线夹角的2倍。", source: "amc10-concept", verified: true },
  { id: "amc10-0373", level: "advance", deck: "geometry", category: "变换", front: "为什么变换复合通常不可交换？", back: "先后顺序改变中间位置；应跟踪一般点验证。", source: "amc10-concept", verified: true },
  { id: "amc10-0374", level: "core", deck: "geometry", category: "立体", front: "组合立体表面积如何避免重复？", back: "各外露面面积相加，粘合面不计且通常需从两物体表面积各减一次。", source: "amc10-concept", verified: true },
  { id: "amc10-0375", level: "advance", deck: "geometry", category: "立体", front: "轴对称圆锥/圆柱相切问题如何降维？", back: "取经过轴线的截面，化成三角形、矩形与内切圆问题。", source: "amc10-concept", verified: true },
  { id: "amc10-0376", level: "advance", deck: "geometry", category: "立体", front: "相似容器液面高度与体积如何联系？", back: "若从顶点起截面保持相似，体积比等于对应高度比的三次方。", source: "amc10-concept", verified: true },
  { id: "amc10-0377", level: "advance", deck: "geometry", category: "立体", front: "平行于棱锥底面的截面有什么性质？", back: "截面与底面相似，长度比等于顶点到截面的高度比。", source: "amc10-concept", verified: true },
  { id: "amc10-0378", level: "advance", deck: "geometry", category: "立体", front: "多面体图距离是什么意思？", back: "把顶点与棱视为图，距离是沿棱走的最少边数，不是空间直线距离。", source: "amc10-concept", verified: true },
  { id: "amc10-0379", level: "advance", deck: "geometry", category: "几何概率", front: "密度不均匀时还能直接用面积比吗？", back: "不能；只有选点关于面积均匀时才用面积比，分块常需用密度×面积作权重。", source: "amc10-concept", verified: true },
  { id: "amc10-0380", level: "core", deck: "counting", category: "组合", front: "去 A 镇可以坐 3 班车或 4 趟火车（中途不换乘），总数为什么是 3+4 而不是 3×4？", back: "“或/要么…要么”表示互斥情形，相加：3+4=7。出现“先…再…”或“每一步都要选一个”才用乘法。", source: "amc10-concept", verified: true },
  { id: "amc10-0381", level: "core", deck: "counting", category: "组合", front: "3 件上衣配 4 条裤子有几种搭配？为什么不是 3+4？", back: "分两步完成（先上衣、再裤子）且每一步的选择数固定，3×4=12；只有互斥的“或”才相加。", source: "amc10-concept", verified: true },
  { id: "amc10-0382", level: "core", deck: "counting", category: "组合", front: "从 5 人中“选 3 人排队”与“选 3 人开会”，结果差多少？", back: "排队 5·4·3=60，开会 C(5,3)=10，差 6=3!。同一批对象：有序用排列、无序用组合，先判断顺序是否算不同。", source: "amc10-concept", verified: true },
  { id: "amc10-0383", level: "core", deck: "counting", category: "组合", front: "5 人排队有多少种排法？0! 为什么等于 1？", back: "5!=120；0! 表示“从 0 个对象里排出 0 个”，只有一种空排列，也让 C(n,n)=1 与公式自洽。", source: "amc10-concept", verified: true },
  { id: "amc10-0384", level: "core", deck: "counting", category: "组合", front: "8 人参赛取前 3 名（名次有区别）有几种结果？", back: "P(8,3)=8·7·6=336。名次有区别=有序，取走一个就少一个，所以依次递减相乘。", source: "amc10-concept", verified: true },
  { id: "amc10-0385", level: "core", deck: "counting", category: "组合", front: "8 人中选 3 人去值日有几种选法？", back: "C(8,3)=56。无顺序，要把 3! 种内部排列除回去：336÷6=56。", source: "amc10-concept", verified: true },
  { id: "amc10-0386", level: "core", deck: "counting", category: "组合", front: "要算 C(10,8)，怎样最快？", back: "用 C(n,r)=C(n,n-r)：C(10,8)=C(10,2)=45，把“选 8 个”换成“不选 2 个”。", source: "amc10-concept", verified: true },
  { id: "amc10-0387", level: "core", deck: "counting", category: "组合", front: "不用计算器，怎样由 C(8,·) 得到 C(9,3)？", back: "Pascal 恒等式：C(9,3)=C(8,2)+C(8,3)=28+56=84，含义是“含某个特定元素”与“不含它”两类。", source: "amc10-concept", verified: true },
  { id: "amc10-0388", level: "core", deck: "counting", category: "组合", front: "6 个元素的集合有多少个子集？", back: "每个元素“选或不选”两种，共 2^6=64，也等于 ΣC(6,r)=1+6+15+20+15+6+1。", source: "amc10-concept", verified: true },
  { id: "amc10-0389", level: "core", deck: "counting", category: "组合", front: "MISSISSIPPI 这 11 个字母能排出多少种不同的串？", back: "11!/(4!4!2!)=34650：除以同字母内部交换数（4 个 S、4 个 I、2 个 P），否则同一串被重复计数。", source: "amc10-concept", verified: true },
  { id: "amc10-0390", level: "core", deck: "counting", category: "组合", front: "6 人围圆桌而坐（只把旋转视为相同）有几种坐法？", back: "(6-1)!=120。直线排列是 6!=720，相差 6=人数；固定一个人当参照就退化成直线排列。", source: "amc10-concept", verified: true },
  { id: "amc10-0391", level: "advance", deck: "counting", category: "组合", front: "2 色 6 珠的手链，只算旋转得 14 种；若反射也算相同，能直接除以 2 吗？", back: "不能得 7，正确是 13。因为有些串在反射下自己不动（如左右对称的串），单纯除 2 会把它们多减；应按每个对称操作数“不动的构型”再平均。", source: "amc10-concept", verified: true },
  { id: "amc10-0392", level: "core", deck: "counting", category: "组合", front: "掷 3 个骰子“至少一个 6”的概率怎样算最快？", back: "用补集：1-(5/6)^3=91/216≈0.421。直接按“恰好 1 个、2 个、3 个 6”分类要分三种且容易漏。", source: "amc10-concept", verified: true },
  { id: "amc10-0393", level: "core", deck: "counting", category: "组合", front: "1 到 100 中能被 3 或 5 整除的数有几个？", back: "33+20-6=47：减去 15 的倍数（6 个），因为它们在两个集合里各被数了一次。", source: "amc10-concept", verified: true },
  { id: "amc10-0394", level: "advance", deck: "counting", category: "组合", front: "1 到 100 中能被 2 或 3 或 5 整除的数有几个？", back: "50+33+20-(16+10+6)+3=74：单集加、两两交减、三交加，符号交替，漏掉最后一项就会少算 3 个（30 的倍数）。", source: "amc10-concept", verified: true },
  { id: "amc10-0395", level: "core", deck: "counting", category: "组合", front: "把 5 个相同球分给 2 人时，“第一人至少 1 个”与“第一人 0 个”这两类够用吗？", back: "够：两类互斥且合起来是全部。若改成“第一人至少 1 个”与“第二人至少 1 个”就出现重叠（如 1+4），会重复计数。", source: "amc10-concept", verified: true },
  { id: "amc10-0396", level: "core", deck: "counting", category: "组合", front: "圆桌 6 人为什么可以固定 1 人当参照？", back: "固定一人即消除旋转造成的重复，余下 5 人做直线排列，得 (6-1)!=120。遇到对称或邻接限制，先固定特殊对象往往能直接消掉重复。", source: "amc10-concept", verified: true },
  { id: "amc10-0397", level: "core", deck: "counting", category: "组合", front: "5 人排队、甲乙必须相邻，有几种排法？", back: "把甲乙捆成一块：4!×2!=48。出现“必须相邻”就用捆绑法，别忘了乘块内 2!。", source: "amc10-concept", verified: true },
  { id: "amc10-0398", level: "core", deck: "counting", category: "组合", front: "5 个 A 与 3 个 B 排成一排、要求 B 互不相邻，有几种？", back: "先排 5 个 A 形成 6 个空位，再选 3 个放 B：C(6,3)=20。同类元素相同，不用再乘 3!；若 A、B 各自不同则还要乘内部排列。", source: "amc10-concept", verified: true },
  { id: "amc10-0399", level: "core", deck: "counting", category: "组合", front: "10 块相同的糖分给 3 个小朋友（允许有人没有）有几种分法？", back: "星与条：C(10+3-1,3-1)=C(12,2)=66。物品相同、盒子不同就用这个模型；盒子不同才有标号。", source: "amc10-concept", verified: true },
  { id: "amc10-0400", level: "core", deck: "counting", category: "组合", front: "x+y+z=10 的非负整数解有几个？", back: "C(12,2)=66，与“10 个相同球分入 3 个不同盒子”是同一件事。", source: "amc10-concept", verified: true },
  { id: "amc10-0401", level: "core", deck: "counting", category: "组合", front: "x+y+z=10 的正整数解有几个？", back: "先给每个变量 1（用掉 3），剩余 7 自由分配：C(9,2)=36。正整数解要求 n≥k，否则无解。", source: "amc10-concept", verified: true },
  { id: "amc10-0402", level: "core", deck: "counting", category: "组合", front: "x+y+z=10 且每个变量不超过 5，解数是多少？能直接套 C(12,2) 吗？", back: "不能，要容斥：66-3·C(6,2)=66-45=21（某变量≥6 时令它减 6，剩 4 分给 3 个变量）。两个变量同时超界不可能，所以无需加回。", source: "amc10-concept", verified: true },
  { id: "amc10-0403", level: "advance", deck: "counting", category: "组合", front: "用 0–9 十个数字（不重复）组成三位偶数，有多少个？", back: "按末位分类：末位为 0 时 9×8=72；末位是 2/4/6/8 时首位不能为 0，4×8×8=256；共 328。首位与末位的限制必须分开处理。", source: "amc10-concept", verified: true },
  { id: "amc10-0404", level: "advance", deck: "counting", category: "组合", front: "从 1–9 中选 3 个数字排成严格递增的三位数，有多少个？", back: "每个选出的集合只有一种递增排法，所以等于 C(9,3)=84。若允许相等，就变成多重组合 C(9+3-1,3)。", source: "amc10-concept", verified: true },
  { id: "amc10-0405", level: "core", deck: "counting", category: "组合", front: "抽屉里有 4 种颜色的袜子，至少取几只才能保证有一双同色？", back: "5 只。最坏情况前 4 只各一色，第 5 只必与其中一只同色（n+1 个对象入 n 个盒子）。", source: "amc10-concept", verified: true },
  { id: "amc10-0406", level: "core", deck: "counting", category: "组合", front: "8 人两两握手一次，用两种方式数会得到什么等式？", back: "按人算：每人 7 次共 56，每场握了 2 次；按场算：2·C(8,2)=56，得 C(8,2)=28。把同一批对象用两种方式数就是双计数。", source: "amc10-concept", verified: true },
  { id: "amc10-0407", level: "core", deck: "counting", category: "组合", front: "能否让 7 个人每人恰好握 3 次手？", back: "不能。总度数为 7×3=21 是奇数，而每条边贡献 2，总和必须为偶数（握手定理）。", source: "amc10-concept", verified: true },
  { id: "amc10-0408", level: "core", deck: "counting", category: "组合", front: "10 个顶点的连通无环图有几条边？", back: "9 条：V-1。树连通又无环，每加入一个顶点恰好加一条边。", source: "amc10-concept", verified: true },
  { id: "amc10-0409", level: "advance", deck: "counting", category: "组合", front: "4 列 3 行的方格网，从左下角走到右上角的最短路径有几条？", back: "C(a+b,a)=C(7,4)=35：路径由 4 步向右、3 步向上构成，只需决定哪几步向右。", source: "amc10-concept", verified: true },
  { id: "amc10-0410", level: "core", deck: "counting", category: "组合", front: "一段楼梯每次跨 1 级或 2 级，上 6 级有几种走法？", back: "a_n=a_{n-1}+a_{n-2}，a_1=1,a_2=2，得 13。按“最后一步跨几级”分类最直接。", source: "amc10-concept", verified: true },
  { id: "amc10-0411", level: "core", deck: "counting", category: "组合", front: "统计长度为 5 的 01 串中“没有相邻两个 1”的个数，递推状态要记什么？", back: "只记最后一位是 0 还是 1（它决定下一步是否受限），共 13 个。状态设计的原则是只保留决定下一步的最少信息。", source: "amc10-concept", verified: true },
  { id: "amc10-0412", level: "advance", deck: "counting", category: "组合", front: "8×8 棋盘剪掉两个对角格后，能用 31 张 1×2 骨牌铺满吗？", back: "不能。棋盘原有 32 黑 32 白，剪掉的两个对角格同色，剩下 30/32；而每张骨牌必盖一黑一白，要求两色数量相等。", source: "amc10-concept", verified: true },
  { id: "amc10-0413", level: "advance", deck: "counting", category: "组合", front: "黑板上写着 9、5、2，每次把最大的数换成另外两数之差的绝对值，这个过程会一直进行下去吗？", back: "不会：(9,5,2)→(5,3,2)→(3,2,1)→(2,1,1)→(1,1,0)，之后状态不再改变。因为新值 |x-y| 不会超过原来的最大数，总和单调不增，最终只能停在 (k,k,0) 形态。注意这里只能断定“不增并稳定”，说成“严格递减”是错的——(1,1,0) 就是反例。", source: "amc10-concept", verified: true },
  { id: "amc10-0414", level: "core", deck: "counting", category: "组合", front: "要证明“n 个点最多 C(n,2) 条边”，需要写哪两步？", back: "①构造：每两点连一条，达到 C(n,2)；②上界：每条边对应一对点，而点对总数只有 C(n,2)。构造给得出、上界证明超不过，合起来才算极值证明。", source: "amc10-concept", verified: true },
  { id: "amc10-0415", level: "advance", deck: "counting", category: "组合", front: "{2,3,5} 与 {1,4,6,9} 哪个是 sum-free 集合？", back: "{2,3,5} 不是，因为 2+3=5 仍在集合内；{1,4,6,9} 是，任意两数（可相同）之和都不在其中。审题要先确认是否允许 x=y。", source: "amc10-concept", verified: true },
  { id: "amc10-0416", level: "advance", deck: "counting", category: "组合", front: "用黑白两色给 1×4 的格子染色且相邻不同色，有几种？", back: "2 种。第一格定下后其余唯一确定；若颜色有标签（“黑”与“白”不同）则第一格有 2 选，答案翻倍，染色题先问颜色是否等价。", source: "amc10-concept", verified: true },
  { id: "amc10-0417", level: "advance", deck: "counting", category: "组合", front: "数“本质不同”的 2×2 黑白染色图案，第一步做什么？", back: "先列出被视为相同的操作集（正方形的 8 个对称：4 个旋转+4 个翻折），再看哪些图案被它们互相转化。不先定操作集，就会把同一个图案重复计入。", source: "amc10-concept", verified: true },
  { id: "amc10-0418", level: "advance", deck: "counting", category: "组合", front: "用两色给正方形的 4 个顶点染色（旋转与翻折都算相同），有几种？", back: "按每个对称操作数不动的构型再平均：(16+2+4+2+4+4+8+8)/8=6。恒等 16；旋转 90°/270° 各固定 2；旋转 180° 固定 4；两条对角线翻折各固定 4；两条中位线翻折各固定 8。AMC 10 只在直接分类很乱时才用它。", source: "amc10-concept", verified: true },
  { id: "amc10-0419", level: "advance", deck: "counting", category: "组合", front: "“1–100 中不含数字 7 的数”与“5 个字母要求某两个不相邻”，哪个用容斥、哪个用递推？", back: "前者是全局禁止（每个位置的限制互相纠缠），用按位分类或补集；后者是局部相邻限制，用递推或插空。全局禁止→容斥，局部相邻→递推/插空。", source: "amc10-concept", verified: true },
  { id: "amc10-0420", level: "core", deck: "counting", category: "概率", front: "掷两个骰子，点数和为 7 的概率是多少？", back: "6/36=1/6：有利结果有 (1,6)…(6,1) 六种。两骰有序，别把 (1,6) 与 (6,1) 当成同一个结果。", source: "amc10-concept", verified: true },
  { id: "amc10-0421", level: "core", deck: "counting", category: "概率", front: "为什么不能把“两骰点数和为 2 到 12”的 11 种和当作等可能？", back: "各和对应的有序结果数不同（和 7 有 6 种，和 2 只有 1 种）。“有利数/总数”只在基本结果等可能时成立，先确认等可能再套公式。", source: "amc10-concept", verified: true },
  { id: "amc10-0422", level: "core", deck: "counting", category: "概率", front: "掷 3 枚硬币“至少一个正面”的概率？", back: "1-P(全反)=1-1/8=7/8。见到“至少”先想补事件。", source: "amc10-concept", verified: true },
  { id: "amc10-0423", level: "core", deck: "counting", category: "概率", front: "已知 P(A)=0.5、P(B)=0.4、P(A∩B)=0.2，P(A∪B) 是多少？", back: "0.5+0.4-0.2=0.7。直接相加会把交集算两次，必须减掉一次。", source: "amc10-concept", verified: true },
  { id: "amc10-0424", level: "core", deck: "counting", category: "概率", front: "袋中 3 红 2 蓝，无放回取两次，已知第一次是红，第二次也是红的概率？", back: "2/4=1/2：条件把样本空间缩到“第一次红”的情形里重新计数，等价于 P(A∩B)/P(B)=(3/5·2/4)/(3/5)。", source: "amc10-concept", verified: true },
  { id: "amc10-0425", level: "core", deck: "counting", category: "概率", front: "掷两个独立骰子时 P(都是 6) 能直接相乘吗？依据是什么？", back: "能：1/36=1/6·1/6，这正是独立的定义 P(A∩B)=P(A)P(B)。一般事件必须用条件概率 P(A)P(B|A)。", source: "amc10-concept", verified: true },
  { id: "amc10-0426", level: "core", deck: "counting", category: "概率", front: "掷一次骰子，“得 1”与“得 2”互斥吗？独立吗？", back: "互斥（不能同时发生），但不独立：一个发生会让另一个的概率变成 0。正概率的互斥事件一定不独立，两个词不能混用。", source: "amc10-concept", verified: true },
  { id: "amc10-0427", level: "core", deck: "counting", category: "概率", front: "52 张牌连抽两张都是 A 的概率，为什么不是 (4/52)²？", back: "无放回时第二次只剩 3 张 A、51 张牌：4/52·3/51=1/221。前一次结果改变了后一次的样本空间，所以不独立。", source: "amc10-concept", verified: true },
  { id: "amc10-0428", level: "core", deck: "counting", category: "概率", front: "某射手命中率 1/3，连射 3 次至少命中一次的概率？", back: "1-(2/3)^3=19/27≈0.704。只有各次独立，才能把“全不中”的概率直接乘起来。", source: "amc10-concept", verified: true },
  { id: "amc10-0429", level: "core", deck: "counting", category: "概率", front: "抛 5 次均匀硬币，恰好 3 次正面的概率？", back: "C(5,3)(1/2)^5=10/32=5/16：先选哪 3 次是正面（组合），再乘每一种顺序的概率。", source: "amc10-concept", verified: true },
  { id: "amc10-0430", level: "core", deck: "counting", category: "概率", front: "随机选一箱：箱 A（被选概率 1/3）有 3 红 2 蓝，箱 B 有 1 红 4 蓝；取到红球的概率？", back: "1/3·3/5+2/3·1/5=1/3。按互斥完备的情形分解目标概率再加权，前提是先把所有能产生目标结果的路径列全。", source: "amc10-concept", verified: true },
  { id: "amc10-0431", level: "advance", deck: "counting", category: "概率", front: "患病率 1%，检测灵敏度 99%、假阳性 5%，检出阳性的人真患病的概率是多少？", back: "0.0099/(0.0099+0.0495)=1/6≈16.7%。分母包含所有产生阳性的路径（大量健康人的假阳性），只看 99% 会把答案高估到接近 1。", source: "amc10-concept", verified: true },
  { id: "amc10-0432", level: "core", deck: "counting", category: "概率", front: "100 人中有 40 名男生，其中 10 人戴眼镜；已知选到的是男生，他戴眼镜的概率？", back: "10/40=1/4。条件把样本空间从 100 人缩到 40 人，分子分母都要跟着换。", source: "amc10-concept", verified: true },
  { id: "amc10-0433", level: "core", deck: "counting", category: "概率", front: "7 人随机排队，甲恰好站在第 3 位的概率？", back: "1/7。由对称性，甲落在任意位置等可能，不必去算 6!/7!。", source: "amc10-concept", verified: true },
  { id: "amc10-0434", level: "core", deck: "counting", category: "概率", front: "5 人随机排队，甲乙相邻的概率？", back: "2/5。把甲乙捆成一块（2! 种）与其余 3 人共 4!  种，除以 5! 得 2/5；对任意 n 人都是 2/n。", source: "amc10-concept", verified: true },
  { id: "amc10-0435", level: "advance", deck: "counting", category: "概率", front: "在单位正方形内均匀取点，它到原点距离小于 1 的概率？", back: "π/4≈0.785：有利区域是以原点为心、半径 1 的四分之一圆。面积模型中概率等于有利面积除以总面积。", source: "amc10-concept", verified: true },
  { id: "amc10-0436", level: "core", deck: "counting", category: "概率", front: "“先均匀取半径、再均匀取角度”得到的点，与“圆盘内均匀取点”相同吗？", back: "不同。圆盘内均匀时半径密度是 2r（越往外环面积越大），按半径均匀取会让内圈偏多。随机机制决定密度，题目必须先说清怎么取。", source: "amc10-concept", verified: true },
  { id: "amc10-0437", level: "advance", deck: "counting", category: "概率", front: "在正方形内均匀取一点，它恰好落在指定对角线上（或恰好距离为 1）的概率？", back: "0：直线与圆周的面积都是 0。但边界仍用来划分区域（求“≥1”或“≤1”时必须靠它），所以不能因为概率为 0 就忽略。", source: "amc10-concept", verified: true },
  { id: "amc10-0438", level: "core", deck: "counting", category: "期望", front: "掷一个均匀骰子的期望是多少？", back: "(1+2+…+6)/6=3.5：按每个取值乘它的概率求和，是加权平均。", source: "amc10-concept", verified: true },
  { id: "amc10-0439", level: "core", deck: "counting", category: "期望", front: "掷一次骰子能掷出 3.5 吗？那期望还有什么用？", back: "不能。期望是长期平均：掷很多次后平均值趋近 3.5。期望不必是可能出现的结果。", source: "amc10-concept", verified: true },
  { id: "amc10-0440", level: "core", deck: "counting", category: "期望", front: "已知 E(X)=4，E(2X+3) 是多少？", back: "2·4+3=11。常数可以提出、可以相加，完全不需要知道 X 的分布。", source: "amc10-concept", verified: true },
  { id: "amc10-0441", level: "core", deck: "counting", category: "期望", front: "同一副牌里第一张与第二张的点数期望能相加吗？需要独立吗？", back: "能。E(X+Y)=E(X)+E(Y) 对任何随机变量都成立，不要求独立——这是最容易误记成“需要独立”的公式。", source: "amc10-concept", verified: true },
  { id: "amc10-0442", level: "core", deck: "counting", category: "期望", front: "怎样把“掷骰得偶数”这个事件写成随机变量？", back: "令 I=1（得偶数）、I=0（否则），则 E(I)=P(偶数)=1/2。指示变量的期望就是事件概率，这是它的全部用途。", source: "amc10-concept", verified: true },
  { id: "amc10-0443", level: "core", deck: "counting", category: "期望", front: "抛 10 次硬币的正面次数 X，怎样用指示变量求 E(X)？", back: "写 X=I_1+…+I_10，每个 E(I_i)=1/2，相加得 5。不用先求 X 的分布。", source: "amc10-concept", verified: true },
  { id: "amc10-0444", level: "core", deck: "counting", category: "期望", front: "把 5 个球随机放进 5 个标号盒（每盒一球），“球在对应编号盒”的个数期望？", back: "每个球设指示变量，概率 1/5，相加得 5×1/5=1。n 个对象随机排列的固定点数期望恒为 1。", source: "amc10-concept", verified: true },
  { id: "amc10-0445", level: "core", deck: "counting", category: "期望", front: "10 个球独立随机放入 3 个盒子，“非空盒数”的期望是多少？", back: "对每个盒子设“非空”指示变量：P(非空)=1-(2/3)^10，所以期望是 3[1-(2/3)^10]≈2.95。空盒数的期望则是 3(2/3)^10。", source: "amc10-concept", verified: true },
  { id: "amc10-0446", level: "core", deck: "counting", category: "期望", front: "公平地抛 6 次硬币，“HH”相邻对出现次数的期望？", back: "共有 5 个相邻位置，每个是 HH 的概率 1/4，相加得 5/4=1.25。这些位置并不独立，但期望线性不要求独立。", source: "amc10-concept", verified: true },
  { id: "amc10-0447", level: "advance", deck: "counting", category: "期望", front: "每次成功概率 1/4 的独立试验，首次成功所需次数 X 的期望用尾和怎样算？", back: "E(X)=Σ_{k≥1}P(X≥k)=Σ(3/4)^{k-1}=1/(1-3/4)=4，与几何分布的 1/p 一致。尾和适合取正整数值的变量。", source: "amc10-concept", verified: true },
  { id: "amc10-0448", level: "advance", deck: "counting", category: "期望", front: "掷两个骰子取较大值的期望是多少？", back: "先算累积：P(M≤m)=(m/6)²，差分得 P(M=m)=[m²-(m-1)²]/36，求和得 161/36≈4.47。求最大值期望先算“≤”的累积更省事。", source: "amc10-concept", verified: true },
  { id: "amc10-0449", level: "advance", deck: "counting", category: "期望", front: "成功概率恒为 1/3、各次独立，首次成功平均需要几次？", back: "1/p=3：写 E=1+失败概率·E 即可解出。若成功概率随轮次变化，必须改用带状态的方程 E_s=1+ΣP(s→t)E_t。", source: "amc10-concept", verified: true },
  { id: "amc10-0450", level: "advance", deck: "counting", category: "随机过程", front: "掷硬币直到出现“正反”序列，平均要掷几次？第一步分析怎么写？", back: "按已匹配的前缀设未知量：p_∅=1+½p_H+½p_∅、p_H=1+½p_H（再抛正面仍停在 H），解得从空状态出发平均 4 次。关键是按“当前匹配到什么前缀”分类。", source: "amc10-concept", verified: true },
  { id: "amc10-0451", level: "advance", deck: "counting", category: "随机过程", front: "端点为 0 和 3 的公平随机游走，从 1 出发先到 3 的概率，第一步写什么？", back: "先写吸收边界 P(0)=0、P(3)=1，再写内部方程 P(i)=½P(i-1)+½P(i+1)，解得 P(1)=1/3。边界不写，方程就解不出确定值。", source: "amc10-concept", verified: true },
  { id: "amc10-0452", level: "advance", deck: "counting", category: "随机过程", front: "公平一维随机游走在两个吸收端点之间，先到右端的概率随起点怎样变化？", back: "线性变化（起点 i 在 0 与 N 之间）。端点值一旦确定就能直接插值，不必逐点解方程。", source: "amc10-concept", verified: true },
  { id: "amc10-0453", level: "advance", deck: "counting", category: "随机过程", front: "从 0 到 8 的公平随机游走，从 5 出发先到 8 的概率？", back: "i/N=5/8。这是上一条线性结论的直接应用：起点越靠右，越容易先碰到右端。", source: "amc10-concept", verified: true },
  { id: "amc10-0454", level: "advance", deck: "counting", category: "随机过程", front: "用递推解出各状态概率后，要检查哪三件事？", back: "①每个概率都落在 0 与 1 之间；②吸收边界的取值符合题意（成功=1、失败=0）；③状态是否覆盖全部可能，遗漏状态会让方程无解或答案偏大。", source: "amc10-concept", verified: true },
  { id: "amc10-0455", level: "advance", deck: "counting", category: "概率", front: "P(A∩B) 能直接写成 P(A)P(B) 吗？", back: "只有独立时才能。一般要用条件乘法 P(A∩B)=P(A)P(B|A)，相关事件（如连续两天下雨）直接相乘会算错。", source: "amc10-concept", verified: true },
  { id: "amc10-0456", level: "advance", deck: "counting", category: "概率", front: "3 个球随机放入 2 个盒子，(3,0) 与 (1,2) 这两种分布的概率一样吗？", back: "不一样。若球彼此独立地选盒，(3,0) 有 2 种结果、(1,2) 有 6 种，概率分别是 2/8 与 6/8。要按每个对象的等可能选择计数，不能把“人数分布”当等可能。", source: "amc10-concept", verified: true },
  { id: "amc10-0457", level: "advance", deck: "counting", category: "概率", front: "两个骰子的点数和 7 与 12，哪个更容易出现？", back: "和 7 有 6 种有序结果、和 12 只有 1 种，概率是 6/36 与 1/36。和值本身不等可能，中间的和更容易出现。", source: "amc10-concept", verified: true },
  { id: "amc10-0458", level: "core", deck: "counting", category: "组合", front: "把 8 张不同的卡片分成 3 张、3 张、2 张三堆（三堆有标签）有多少种分法？", back: "8!/(3!3!2!)=560：先决定每堆成员，再除掉各堆内部的顺序（堆内无序）。", source: "amc10-concept", verified: true },
  { id: "amc10-0459", level: "core", deck: "counting", category: "组合", front: "把 6 人分成两队各 3 人，为什么要多除一次 2!？", back: "两队有名字（A 队/B 队）时是 C(6,3)=20；没有名字时交换两队得到同一分法，要再除 2!=2，得 10。盒子是否有标号决定要不要去重。", source: "amc10-concept", verified: true },
  { id: "amc10-0460", level: "advance", deck: "counting", category: "组合", front: "6 人平均分成 3 组（每组 2 人、组无名字）有几种分法？", back: "先按有标号组数：C(6,2)C(4,2)C(2,2)=90，再除 3!=6，得 15。只有组大小相同时才除组数的阶乘。", source: "amc10-concept", verified: true },
  { id: "amc10-0461", level: "advance", deck: "counting", category: "组合", front: "“把 3 分成几个正整数之和”与“x+y=3 的非负整数解”有什么不同？", back: "整数分拆不计加数顺序：3 只有 3、2+1、1+1+1 三种；方程解有标号变量、计顺序：x+y=3 有 (0,3)(1,2)(2,1)(3,0) 四个。", source: "amc10-concept", verified: true },
  { id: "amc10-0462", level: "core", deck: "counting", category: "组合", front: "排列 3142 的逆序对有多少对？", back: "3 对：3>1、3>2、4>2。逐个数“它前面有几个比它大”再相加是最常见的数法。", source: "amc10-concept", verified: true },
  { id: "amc10-0463", level: "advance", deck: "counting", category: "组合", front: "交换排列中相邻的两个元素，逆序对数的奇偶性会怎样变？", back: "恰好改变 1（这两个元素的相对次序翻转，与其余元素的次序都不变），所以奇偶性翻转。这正是“相邻交换改变排列奇偶性”的来源。", source: "amc10-concept", verified: true },
  { id: "amc10-0464", level: "core", deck: "counting", category: "组合", front: "8 人循环赛（每两人赛一场）共几场？", back: "C(8,2)=28：一场比赛对应一对选手，顺序无关。", source: "amc10-concept", verified: true },
  { id: "amc10-0465", level: "advance", deck: "counting", category: "组合", front: "圆上 6 个点两两连线（没有三条弦共点），圆内有多少个交点？", back: "C(6,4)=15：每个交点唯一对应 4 个点（它们的两条对角线相交）。漏掉“每 4 点决定一个交点”就会重复计数。", source: "amc10-concept", verified: true },
  { id: "amc10-0466", level: "advance", deck: "counting", category: "组合", front: "第 n 条一般位置直线最多把平面分成几块？5 条呢？", back: "第 n 条直线被已有 n-1 个交点分成 n 段，就新增 n 块：区域数 1+n(n+1)/2，n=5 时是 16。必须保证是一般位置（无平行、无三线共点）。", source: "amc10-concept", verified: true },
  { id: "amc10-0467", level: "advance", deck: "counting", category: "组合", front: "4 封信全部装错信封有多少种装法？", back: "错排 D_4=9：容斥 4!-C(4,1)3!+C(4,2)2!-C(4,3)1!+C(4,4)0!=24-24+12-4+1=9。", source: "amc10-concept", verified: true },
  { id: "amc10-0468", level: "advance", deck: "counting", category: "组合", front: "已知 D_3=2、D_4=9，D_5 是多少？", back: "D_n=(n-1)(D_{n-1}+D_{n-2})=4×(9+2)=44。递推比容斥快，n 较大时用递推。", source: "amc10-concept", verified: true },
  { id: "amc10-0469", level: "advance", deck: "counting", category: "组合", front: "4 对括号能组成多少种合法括号序列？", back: "Catalan 数 C_4=14，等于“前缀中右括号从不多于左括号”的路径数。识别信号就是这种“始终不越界的前缀”，它不在 AMC 10 必背范围内。", source: "amc10-concept", verified: true },
  { id: "amc10-0470", level: "advance", deck: "counting", category: "组合", front: "{1,2,3} 的所有子集中，“任意两个互不包含”的集合族最多能取几个？", back: "取中间层最大，如 {1},{2},{3} 共 3 个（等于 C(3,1)=C(3,2)）。反链题的典型答案是中间层，可用双计数证明最优。", source: "amc10-concept", verified: true },
  { id: "amc10-0471", level: "advance", deck: "counting", category: "组合", front: "3 人比赛允许并列，有多少种排名方式？", back: "13 种：按并列块数分类——1 块 1 种（全并列），2 块 3×2=6 种，3 块 1 种，合计 13。必须先说明并列后是否跳过后续名次。", source: "amc10-concept", verified: true },
  { id: "amc10-0472", level: "advance", deck: "counting", category: "组合", front: "给一条 5 格带子染色、要求相邻不同色，递推状态记什么？", back: "只记上一格的颜色（以及与更前一格是否相同），不必保存整条带子的历史。状态设计的原则是只保留决定下一步的最少信息。", source: "amc10-concept", verified: true },
  { id: "amc10-0473", level: "core", deck: "counting", category: "概率", front: "10 件产品中有 3 件次品，任取 4 件恰好 1 件次品的概率？", back: "C(3,1)C(7,3)/C(10,4)=105/210=1/2。无放回抽取用超几何：分子分别选次品与正品，分母选全部。", source: "amc10-concept", verified: true },
  { id: "amc10-0474", level: "advance", deck: "counting", category: "概率", front: "5 个不同球独立随机放入 3 个盒子，“一个盒 2 个、另一个盒 2 个、第三个盒 1 个”的概率？", back: "先选哪个盒装 1 个（3 种），每种分布有 5!/(2!2!1!)=30 个结果，共 90；除以 3^5=243，得 90/243≈0.370。", source: "amc10-concept", verified: true },
  { id: "amc10-0475", level: "core", deck: "counting", category: "概率", front: "从 12 的约数中随机取一个，取到大于 6 的概率是多少？", back: "约数是 1,2,3,4,6,12 共 6 个，大于 6 的只有 12，概率 1/6。均匀的是约数列表中的对象，不能按数值区间假设均匀。", source: "amc10-concept", verified: true },
  { id: "amc10-0476", level: "advance", deck: "counting", category: "概率", front: "已知各种情形下的 P(A|B_i)，怎样求 P(A)？", back: "对互斥完备的 B_i 用全概率公式 P(A)=ΣP(A|B_i)P(B_i)。前提是 B_i 两两互斥且并集为全集，漏一种情形就会算少。", source: "amc10-concept", verified: true },
  { id: "amc10-0477", level: "advance", deck: "counting", category: "概率", front: "已知各类情形下的条件期望，怎样合并成 E(X)？", back: "用分层公式 E(X)=ΣE(X|B_i)P(B_i)，按情形概率加权平均，前提同样是情形互斥完备。", source: "amc10-concept", verified: true },
  { id: "amc10-0478", level: "advance", deck: "counting", category: "期望", front: "E(XY)=E(X)E(Y) 什么时候成立？", back: "只有 X、Y 独立时。一般必须用联合分布计算；不独立时相关性会把乘积的期望拉偏。", source: "amc10-concept", verified: true },
  { id: "amc10-0479", level: "advance", deck: "counting", category: "期望", front: "方差的定义式与计算式分别是什么？", back: "Var(X)=E[(X-E(X))²]=E(X²)-[E(X)]²。计算式更快，但两次都要用到期望线性。", source: "amc10-concept", verified: true },
  { id: "amc10-0480", level: "advance", deck: "counting", category: "期望", front: "成功概率为 p 的指示变量的期望与方差是多少？", back: "E=p，Var=p(1-p)（因为 X²=X）。p=1/2 时方差最大，为 0.25。", source: "amc10-concept", verified: true },
  { id: "amc10-0481", level: "advance", deck: "counting", category: "期望", front: "求最小值 M 的期望，用尾和怎么写？", back: "E(M)=Σ_{k≥1}P(M≥k)，而 P(M≥k) 通常比 P(M=k) 好算（“所有变量都≥k”）。也可以直接列 M 的分布。", source: "amc10-concept", verified: true },
  { id: "amc10-0482", level: "advance", deck: "counting", category: "随机过程", front: "吸收随机过程的期望步数方程怎么写？", back: "非终止状态 E_s=1+ΣP(s→t)E_t，终止状态为 0（或按题意取值）。1+ 代表这一步本身，别漏掉。", source: "amc10-concept", verified: true },
  { id: "amc10-0483", level: "advance", deck: "counting", category: "随机过程", front: "随机游走中两个状态未来行为完全相同时怎么办？", back: "把它们合并成同一个未知量，方程数立刻减少。判断标准是“未来的转移概率分布相同”，而不是位置看起来对称。", source: "amc10-concept", verified: true },
  { id: "amc10-0484", level: "advance", deck: "counting", category: "概率", front: "4 人单败淘汰赛：甲首轮对小乙（甲必胜），另一场小丙对小丁（丙必胜），决赛甲对丙甲胜率 1/2。甲夺冠概率？", back: "1×1×1/2=1/2：沿“下一场对手”逐轮把当前轮概率乘以后续条件概率。若对手不确定，还要按对手出现的概率加权相加。", source: "amc10-concept", verified: true },
  { id: "amc10-0485", level: "advance", deck: "counting", category: "概率", front: "已观测到“最终成功”，为什么早期某些分支的概率要重新下调？", back: "因为各分支通向成功的概率不同：P(分支|成功)=P(成功|分支)P(分支)/P(成功)，低产分支被压低。这类事后反推必须用 Bayes 重新加权，不能沿用先验比例。", source: "amc10-concept", verified: true },
  { id: "amc10-0486", level: "core", deck: "strategy", category: "方法", front: "文字题第一步是什么？", back: "定义变量并写单位，再把每句话翻译成关系式。", source: "amc10-concept", verified: true },
  { id: "amc10-0487", level: "core", deck: "strategy", category: "方法", front: "图形题第一步是什么？", back: "重画清晰图，标已知、等长、平行、直角和目标量；不依赖比例尺。", source: "amc10-concept", verified: true },
  { id: "amc10-0488", level: "core", deck: "strategy", category: "方法", front: "复杂题如何寻找不变量？", back: "比较操作前后不变的奇偶、和、积、余数、颜色或距离关系。", source: "amc10-concept", verified: true },
  { id: "amc10-0489", level: "core", deck: "strategy", category: "方法", front: "对称性有什么直接用途？", back: "减少分类、确定相等量、固定代表或推出期望相同。", source: "amc10-concept", verified: true },
  { id: "amc10-0490", level: "core", deck: "strategy", category: "方法", front: "极端原则是什么？", back: "选最大、最小、最左等极端对象，利用其不能继续延伸的限制。", source: "amc10-concept", verified: true },
  { id: "amc10-0491", level: "core", deck: "strategy", category: "方法", front: "反证法结构是什么？", back: "假设结论不成立，推导与已知、定义或基本事实矛盾。", source: "amc10-concept", verified: true },
  { id: "amc10-0492", level: "core", deck: "strategy", category: "方法", front: "构造题怎样证明答案确实最优？", back: "同时给合法构造和与方向匹配的界：求最大值证不可超过的上界，求最小值证不可低于的下界。", source: "amc10-concept", verified: true },
  { id: "amc10-0493", level: "core", deck: "strategy", category: "方法", front: "测试小规模有什么用？", back: "发现模式、检验猜想和边界；不能替代一般证明。", source: "amc10-concept", verified: true },
  { id: "amc10-0494", level: "core", deck: "strategy", category: "方法", front: "代答案什么时候有效？", back: "选择题中选项简单、方程逆解麻烦且能快速排除时。", source: "amc10-concept", verified: true },
  { id: "amc10-0495", level: "core", deck: "strategy", category: "方法", front: "取特殊值什么时候安全？", back: "用于排除恒等式或发现规律；证明一般结论仍需覆盖全部情况。", source: "amc10-concept", verified: true },
  { id: "amc10-0496", level: "core", deck: "strategy", category: "方法", front: "维度分析能排除什么？", back: "单位或次数错误，如面积答案却具有长度单位。", source: "amc10-concept", verified: true },
  { id: "amc10-0497", level: "advance", deck: "strategy", category: "方法", front: "齐次性有什么用？", back: "所有项同次数时可按比例缩放，常可令某个和、积或长度为1。", source: "amc10-concept", verified: true },
  { id: "amc10-0498", level: "advance", deck: "strategy", category: "方法", front: "双向夹逼完成最值的结构是什么？", back: "先证明目标≤M或≥m，再给等号可达实例。", source: "amc10-concept", verified: true },
  { id: "amc10-0499", level: "advance", deck: "strategy", category: "方法", front: "代数题几何化的常见信号是什么？", back: "出现距离根式、平方和、绝对值或固定和积。", source: "amc10-concept", verified: true },
  { id: "amc10-0500", level: "advance", deck: "strategy", category: "方法", front: "几何题代数化的常见信号是什么？", back: "大量直角、平行、比例、坐标或规则变换。", source: "amc10-concept", verified: true },
  { id: "amc10-0501", level: "core", deck: "strategy", category: "方法", front: "多种解法如何选择？", back: "优先条件少、计算短、验根清楚且不易出错的方法。", source: "amc10-concept", verified: true },
  { id: "amc10-0502", level: "core", deck: "strategy", category: "英文", front: "integer与whole number通常分别指什么？", back: "integer为整数；whole number通常指非负整数，仍以题目定义为准。", source: "amc10-concept", verified: true },
  { id: "amc10-0503", level: "core", deck: "strategy", category: "英文", front: "positive integer是否包含0？", back: "不包含。", source: "amc10-concept", verified: true },
  { id: "amc10-0504", level: "core", deck: "strategy", category: "英文", front: "distinct是什么意思？", back: "互不相同。", source: "amc10-concept", verified: true },
  { id: "amc10-0505", level: "core", deck: "strategy", category: "英文", front: "at least与at most是什么意思？", back: "至少≥；至多≤。", source: "amc10-concept", verified: true },
  { id: "amc10-0506", level: "core", deck: "strategy", category: "英文", front: "no more than与no less than是什么意思？", back: "不超过≤；不少于≥。", source: "amc10-concept", verified: true },
  { id: "amc10-0507", level: "core", deck: "strategy", category: "英文", front: "consecutive integers是什么意思？", back: "连续整数，相邻差1。", source: "amc10-concept", verified: true },
  { id: "amc10-0508", level: "core", deck: "strategy", category: "英文", front: "factor、multiple、divisor分别是什么？", back: "factor/divisor为因数；multiple为倍数。", source: "amc10-concept", verified: true },
  { id: "amc10-0509", level: "core", deck: "strategy", category: "英文", front: "remainder是什么意思？", back: "余数，需满足通常的0≤r<m。", source: "amc10-concept", verified: true },
  { id: "amc10-0510", level: "core", deck: "strategy", category: "英文", front: "chosen uniformly at random是什么意思？", back: "从指定基本结果中等概率选择。", source: "amc10-concept", verified: true },
  { id: "amc10-0511", level: "core", deck: "strategy", category: "英文", front: "without replacement是什么意思？", back: "不放回，后续选择通常受前次影响。", source: "amc10-concept", verified: true },
  { id: "amc10-0512", level: "core", deck: "strategy", category: "英文", front: "expected number是什么意思？", back: "某个计数型随机变量的期望，不是最可能数量。", source: "amc10-concept", verified: true },
  { id: "amc10-0513", level: "core", deck: "strategy", category: "英文", front: "tangent、secant、chord分别是什么？", back: "切线、割线、弦。", source: "amc10-concept", verified: true },
  { id: "amc10-0514", level: "core", deck: "strategy", category: "英文", front: "circumcircle与incircle是什么？", back: "外接圆与内切圆。", source: "amc10-concept", verified: true },
  { id: "amc10-0515", level: "core", deck: "strategy", category: "英文", front: "perpendicular bisector是什么？", back: "垂直平分线。", source: "amc10-concept", verified: true },
  { id: "amc10-0516", level: "core", deck: "strategy", category: "英文", front: "centroid、incenter、circumcenter、orthocenter是什么？", back: "重心、内心、外心、垂心。", source: "amc10-concept", verified: true },
  { id: "amc10-0517", level: "core", deck: "strategy", category: "英文", front: "similar与congruent有什么区别？", back: "相似允许缩放；全等大小形状都相同。", source: "amc10-concept", verified: true },
  { id: "amc10-0518", level: "core", deck: "strategy", category: "英文", front: "a figure is inscribed in a circle是什么意思？", back: "图形顶点在圆上。", source: "amc10-concept", verified: true },
  { id: "amc10-0519", level: "core", deck: "strategy", category: "英文", front: "a circle is inscribed in a polygon是什么意思？", back: "圆与多边形各边相切。", source: "amc10-concept", verified: true },
  { id: "amc10-0520", level: "core", deck: "strategy", category: "英文", front: "maximum possible与minimum possible要求什么？", back: "不仅算界，还要确认该界能被合法对象达到。", source: "amc10-concept", verified: true },
  { id: "amc10-0521", level: "core", deck: "strategy", category: "英文", front: "not necessarily drawn to scale提醒什么？", back: "不能凭图目测长度、角度或相交位置。", source: "amc10-concept", verified: true },
  { id: "amc10-0522", level: "core", deck: "strategy", category: "策略", front: "AMC 10整卷结构是什么？", back: "25道五选一，通常75分钟；当年规则仍须在MAA官网确认。", source: "amc10-concept", verified: true },
  { id: "amc10-0523", level: "core", deck: "strategy", category: "策略", front: "第一轮做题目标是什么？", back: "快速完成确定会做的题，不让一道难题吞掉时间。", source: "amc10-concept", verified: true },
  { id: "amc10-0524", level: "core", deck: "strategy", category: "策略", front: "什么时候应暂时跳题？", back: "约2–3分钟仍无清晰进展、计算失控或模型尚未识别时。", source: "amc10-concept", verified: true },
  { id: "amc10-0525", level: "core", deck: "strategy", category: "策略", front: "涂卡前应检查什么？", back: "题号、选项、是否错位以及空题策略。", source: "amc10-concept", verified: true },
  { id: "amc10-0526", level: "core", deck: "strategy", category: "策略", front: "数值答案应做哪三项检查？", back: "符号、数量级、单位/范围。", source: "amc10-concept", verified: true },
  { id: "amc10-0527", level: "core", deck: "strategy", category: "策略", front: "几何答案应做什么合理性检查？", back: "长度为正、角度范围正确、面积不超过容器、比例符合图形关系。", source: "amc10-concept", verified: true },
  { id: "amc10-0528", level: "core", deck: "strategy", category: "策略", front: "概率答案的范围是什么？", back: "0到1；期望则不受此范围限制。", source: "amc10-concept", verified: true },
  { id: "amc10-0529", level: "core", deck: "strategy", category: "策略", front: "整数题最后要检查什么？", back: "正/非负要求、整除、奇偶、范围和是否重复计数。", source: "amc10-concept", verified: true },
  { id: "amc10-0530", level: "core", deck: "strategy", category: "策略", front: "错题分类至少有哪些？", back: "知识漏洞、模型识别、计算、读题、时间管理。", source: "amc10-concept", verified: true },
  { id: "amc10-0531", level: "core", deck: "strategy", category: "策略", front: "错题复测为何不能只看答案？", back: "熟悉答案不等于能独立重建解法；应闭卷重做并解释触发点。", source: "amc10-concept", verified: true },
  { id: "amc10-0532", level: "core", deck: "strategy", category: "策略", front: "推荐复测间隔是什么？", back: "约48小时、7天、21天，根据遗忘情况调整。", source: "amc10-concept", verified: true },
  { id: "amc10-0533", level: "boundary", deck: "strategy", category: "范围", front: "AMC 10核心数学范围是什么？", back: "初等代数、初等几何、数论、计数与概率及其综合问题。", source: "amc10-concept", verified: true },
  { id: "amc10-0534", level: "boundary", deck: "strategy", category: "范围", front: "微积分是否属于AMC 10必需范围？", back: "不属于。", source: "amc10-concept", verified: true },
  { id: "amc10-0535", level: "boundary", deck: "strategy", category: "范围", front: "三角函数是否属于AMC 10官方核心范围？", back: "不属于；特殊三角形和几何关系足够。", source: "amc10-concept", verified: true },
  { id: "amc10-0536", level: "boundary", deck: "strategy", category: "范围", front: "复数是否应作为优先专题？", back: "不是AMC 10备考优先内容，除非个人拓展。", source: "amc10-concept", verified: true },
  { id: "amc10-0537", level: "boundary", deck: "strategy", category: "范围", front: "高级不等式是否应先于基础方法？", back: "不应；AM-GM、Cauchy、Titu、配方、三角不等式和取等检查优先。", source: "amc10-concept", verified: true },
  { id: "amc10-0538", level: "boundary", deck: "strategy", category: "范围", front: "Burnside、生成函数是否必须？", back: "不是；只作为少量高难对称/计数题的提高工具。", source: "amc10-concept", verified: true },
  { id: "amc10-0539", level: "boundary", deck: "strategy", category: "范围", front: "近五年低频是否等于不会考？", back: "不等于；频率用于分配训练，不是删减考纲或押题。", source: "amc10-concept", verified: true },
  { id: "amc10-0540", level: "boundary", deck: "strategy", category: "范围", front: "Flashcards能否替代完整做题？", back: "不能；卡片负责记忆与识别，真题负责建模、计算和时间压力。", source: "amc10-concept", verified: true },
  { id: "amc10-0541", level: "core", deck: "strategy", category: "逻辑", front: "命题是什么？", back: "能明确判断真或假的陈述句。", source: "amc10-concept", verified: true },
  { id: "amc10-0542", level: "core", deck: "strategy", category: "逻辑", front: "命题P的否定是什么？", back: "“P不成立”；否定必须覆盖P以外的全部情况。", source: "amc10-concept", verified: true },
  { id: "amc10-0543", level: "core", deck: "strategy", category: "逻辑", front: "“所有对象都满足P”的否定是什么？", back: "“至少存在一个对象不满足P”。", source: "amc10-concept", verified: true },
  { id: "amc10-0544", level: "core", deck: "strategy", category: "逻辑", front: "“至少存在一个对象满足P”的否定是什么？", back: "“所有对象都不满足P”。", source: "amc10-concept", verified: true },
  { id: "amc10-0545", level: "core", deck: "strategy", category: "逻辑", front: "蕴含P→Q什么时候为假？", back: "仅当P真而Q假。", source: "amc10-concept", verified: true },
  { id: "amc10-0546", level: "core", deck: "strategy", category: "逻辑", front: "P→Q的逆命题是什么？", back: "Q→P，不一定与原命题等价。", source: "amc10-concept", verified: true },
  { id: "amc10-0547", level: "core", deck: "strategy", category: "逻辑", front: "P→Q的逆否命题是什么？", back: "非Q→非P，与原命题等价。", source: "amc10-concept", verified: true },
  { id: "amc10-0548", level: "core", deck: "strategy", category: "逻辑", front: "“P是Q的充分条件”是什么意思？", back: "P→Q。", source: "amc10-concept", verified: true },
  { id: "amc10-0549", level: "core", deck: "strategy", category: "逻辑", front: "“P是Q的必要条件”是什么意思？", back: "Q→P。", source: "amc10-concept", verified: true },
  { id: "amc10-0550", level: "core", deck: "strategy", category: "逻辑", front: "“当且仅当”要求证明什么？", back: "两个方向都成立。", source: "amc10-concept", verified: true },
  { id: "amc10-0551", level: "core", deck: "strategy", category: "逻辑", front: "一个反例能推翻什么？", back: "“所有……都……”或“必然……”型全称命题。", source: "amc10-concept", verified: true },
  { id: "amc10-0552", level: "core", deck: "strategy", category: "逻辑", front: "一个例子能证明“可能”吗？", back: "能；但不能证明“总是”。", source: "amc10-concept", verified: true },
  { id: "amc10-0553", level: "core", deck: "strategy", category: "逻辑", front: "真假话题的稳健方法是什么？", back: "为每个人/陈述设真假状态，逐条翻译并排除矛盾。", source: "amc10-concept", verified: true },
  { id: "amc10-0554", level: "advance", deck: "strategy", category: "逻辑", front: "自指陈述题先检查什么？", back: "假设它真或假是否分别自洽；不要凭语感判断。", source: "amc10-concept", verified: true },
  { id: "amc10-0555", level: "advance", deck: "strategy", category: "逻辑", front: "信息推断题如何证明答案唯一？", back: "列出所有初始可能，逐条筛选，最后确认只剩一个。", source: "amc10-concept", verified: true },
  { id: "amc10-0556", level: "core", deck: "strategy", category: "证明", front: "直接证明的结构是什么？", back: "从已知出发，用定义和已知定理逐步推出结论。", source: "amc10-concept", verified: true },
  { id: "amc10-0557", level: "core", deck: "strategy", category: "证明", front: "分类证明怎样保证完整？", back: "分类条件互斥并覆盖所有可能，边界单独确认。", source: "amc10-concept", verified: true },
  { id: "amc10-0558", level: "advance", deck: "strategy", category: "证明", front: "交换论证如何证明贪心选择不劣？", back: "把任一最优解的局部选择换成贪心选择，证明可行且目标不变差。", source: "amc10-concept", verified: true },
  { id: "amc10-0559", level: "advance", deck: "strategy", category: "证明", front: "归纳法的两步是什么？", back: "验证基础情形；假设第n情形成立并推出第n+1情形。", source: "amc10-concept", verified: true },
  { id: "amc10-0560", level: "core", deck: "strategy", category: "策略", front: "“会背公式但不会启动”应补哪类卡？", back: "补“题面结构→首选方法”的识别卡，而不是重复公式卡。", source: "amc10-concept", verified: true },
  { id: "amc10-0561", level: "core", deck: "strategy", category: "策略", front: "每张知识卡怎样连接做题？", back: "至少绑定一道例题/真题题号，并记录首次独立做对日期。", source: "amc10-concept", verified: true },
  { id: "amc10-0562", level: "core", deck: "strategy", category: "策略", front: "卡片回答到什么程度才算通过？", back: "不只说公式，还要说适用条件、取等/边界和一个典型触发词。", source: "amc10-concept", verified: true },
  { id: "amc10-0563", level: "core", deck: "strategy", category: "策略", front: "如何防止卡片过大？", back: "一张只问一个可独立判定的问题；定义、公式、条件、陷阱必要时拆开。", source: "amc10-concept", verified: true },
  { id: "amc10-0564", level: "core", deck: "strategy", category: "策略", front: "如何防止只会正向回忆？", back: "同一重要知识同时做“名称→公式”和“结构→方法”两种方向的卡。", source: "amc10-concept", verified: true },
];
